window.SSAI_TERMS=[{"subject":"論理国語","topics":[{"topic":"文章の構成と接続語","cards":[{"term":"序論・本論・結論","reading":"じょろん・ほんろん・けつろん","meaning":"文章全体を問題提起、展開、まとめの三つに分ける基本的な組み立て。","note":"このテーマの土台。評論を読むときはまず三部構成を意識する。"},{"term":"順接","reading":"じゅんせつ","meaning":"前の内容を受けて、自然な結果や続きが後ろに来る関係。「だから」などが示す。","note":"因果や流れをつかむ手がかりになる接続関係。"},{"term":"逆接","reading":"ぎゃくせつ","meaning":"前の内容から予想される流れに反する内容が続く関係。「しかし」などが示す。","note":"筆者の主張が現れやすい転換点として重要。"},{"term":"添加・並列","reading":"てんか・へいれつ","meaning":"似た内容を付け加えたり並べたりする関係。「また」「さらに」などが示す。","note":"情報を増やして説明を厚くする働きをする。"},{"term":"対比の接続語","reading":"たいひのせつぞくご","meaning":"二つの事柄を比べる関係を示す言葉。「一方」「これに対して」など。","note":"違いを際立たせることで主張を明確にする。"},{"term":"換言の接続語","reading":"かんげんのせつぞくご","meaning":"前の内容を別の言葉で言い直すことを示す言葉。「つまり」「すなわち」など。","note":"要旨や結論がまとめられる場所の目印になる。"}]},{"topic":"段落の役割と要旨","cards":[{"term":"段落","reading":"だんらく","meaning":"一つのまとまった内容ごとに改行して区切った文章の単位。","note":"段落ごとに役割を考えるのが読み取りの第一歩。"},{"term":"中心文","reading":"ちゅうしんぶん","meaning":"段落の要点を最も直接に表した一文。話題文とも呼ばれる。","note":"段落の要旨をつかむときの核になる文。"},{"term":"要旨","reading":"ようし","meaning":"文章全体や段落で筆者が最も伝えたい内容を短くまとめたもの。","note":"中心文と具体例を区別して見つける。"},{"term":"具体例の段落","reading":"ぐたいたいのだんらく","meaning":"抽象的な主張を分かりやすくするために実例を示す段落。","note":"主張そのものではないので要旨と混同しない。"},{"term":"話題の転換","reading":"わだいのてんかん","meaning":"段落が変わり、扱う内容や視点が切り替わること。","note":"逆接の接続語や新しい語句が合図になることが多い。"},{"term":"段落構成図","reading":"だんらくこうせいず","meaning":"各段落の役割とつながりを図に整理したもの。","note":"文章全体の論の流れを一目で確認できる。"}]},{"topic":"論理の展開と根拠","cards":[{"term":"主張","reading":"しゅちょう","meaning":"筆者が読み手に納得してほしい中心的な考え。","note":"根拠と結び付けて読む対象。"},{"term":"根拠","reading":"こんきょ","meaning":"主張を支える理由や証拠となる事柄。","note":"根拠が十分かどうかで論の説得力が決まる。"},{"term":"帰納法","reading":"きのうほう","meaning":"個別の事例をいくつか集め、そこから共通する結論を導く考え方。","note":"具体例から一般的な主張へ進む展開で使われる。"},{"term":"演繹法","reading":"えんえきほう","meaning":"一般的な原理や前提から出発し、個別の結論を導く考え方。","note":"前提が正しいかどうかが結論の信頼性を左右する。"},{"term":"論理の飛躍","reading":"ろんりのひやく","meaning":"根拠から結論までの間に必要な説明が抜け、つながりが不十分なこと。","note":"批判的に読むときに見つけるべき弱点。"},{"term":"事実と意見","reading":"じじつといけん","meaning":"実際に起きた事柄と、それに対する考えや評価を区別すること。","note":"根拠として使えるのはまず事実であり、意見は主張側に置く。"}]},{"topic":"対比と例示","cards":[{"term":"対比","reading":"たいひ","meaning":"二つの事柄を並べて比べ、共通点や相違点を明らかにすること。","note":"筆者の考えを浮かび上がらせる代表的な方法。"},{"term":"二項対立","reading":"にこうたいりつ","meaning":"物事を二つの対立する項に分けて捉える枠組み。","note":"分かりやすい反面、単純化しすぎる危険もある。"},{"term":"例示","reading":"れいじ","meaning":"抽象的な説明の後に具体的な事例を示して理解を助けること。","note":"「たとえば」で始まる部分が目印になる。"},{"term":"類比","reading":"るいひ","meaning":"似た構造を持つ別の事柄になぞらえて説明する方法。アナロジーともいう。","note":"比喩的な説明と論証の区別に注意する。"},{"term":"具体と抽象の往復","reading":"ぐたいとちゅうしょうのおうふく","meaning":"具体例と一般的な考えを行き来しながら理解を深める読み方。","note":"例示と対比を読み解くときの基本動作。"}]},{"topic":"抽象と具体","cards":[{"term":"抽象","reading":"ちゅうしょう","meaning":"個別の事柄から共通する性質を取り出し、一般的に捉えること。","note":"具体例を束ねて大きな考えを作る働き。"},{"term":"具体","reading":"ぐたい","meaning":"形や様子がはっきり分かる、個別で実際の事柄のこと。","note":"抽象的な主張を確かめる材料になる。"},{"term":"上位概念と下位概念","reading":"じょういがいねんとかいがいねん","meaning":"広く含む概念と、その中に含まれる狭い概念の関係。","note":"例として「乗り物」が上位、「自転車」が下位にあたる。"},{"term":"一般化","reading":"いっぱんか","meaning":"限られた事例から、広く当てはまる言い方へ広げること。","note":"広げすぎると根拠不足になる点に注意する。"},{"term":"定義","reading":"ていぎ","meaning":"言葉の意味する範囲を明確に定める説明。","note":"論を始める前に用語をそろえる役割を持つ。"},{"term":"抽象化の落とし穴","reading":"ちゅうしょうかのはとしあな","meaning":"抽象的にまとめる過程で大事な違いが消えてしまう問題。","note":"具体に戻って確かめることで防げる。"}]},{"topic":"働くということ","cards":[{"term":"労働と仕事の違い","reading":"ろうどうとしごとのちがい","meaning":"労働は賃金を得る活動の面、仕事は社会的な役割ややりがいを含む面に注目した捉え方。","note":"本文では二つの言葉の使い分けが主張の鍵になる。"},{"term":"言葉と仕事","reading":"ことばとしごと","meaning":"言葉の意味の捉え方が、その活動への価値づけに影響するという考え。","note":"テーマ全体を貫く視点。"},{"term":"楽しく働く／楽に働く","reading":"たのしくはたらく／らくにはたらく","meaning":"充実感を得ながら働くことと、負担の少なさを求めて働くことの対比。","note":"筆者が区別する二つの働き方。"},{"term":"社会との関わり","reading":"しゃかいとのかかわり","meaning":"働くことが他者や社会の役に立つことと結び付いているという面。","note":"仕事の意味を個人の外へ広げる論点。"},{"term":"問いを立てる","reading":"といをたてる","meaning":"答えを探す前に、自分が何を疑問に思うかを言葉にすること。","note":"評論を読むときにも使える主体的な姿勢。"}]},{"topic":"論理の力―論理とは何か","cards":[{"term":"つながる力","reading":"つながるちから","meaning":"言葉と言葉、考えと考えを筋道立てて結び付ける論理の働き。","note":"論理の四つの力の一つとして示される。"},{"term":"結論する力","reading":"けつろんするちから","meaning":"根拠を踏まえて自分の判断をまとめる論理の働き。","note":"曖昧なまま終わらせないための力。"},{"term":"整理する力","reading":"せいりするちから","meaning":"情報を分けたり順序付けたりして分かりやすくする働き。","note":"複雑な内容を扱うときの土台になる。"},{"term":"質問する力","reading":"しつもんするちから","meaning":"前提を疑い、不足している点を問うことで考えを深める働き。","note":"論理は答えるだけでなく問う力でもある。"},{"term":"演繹","reading":"えんえき","meaning":"一般的な前提から個別の結論を必然的に導く推論。","note":"このテーマでは論理の代表例として帰納と並べて扱う。"},{"term":"帰納","reading":"きのう","meaning":"複数の事例から共通する傾向を見つけ、一般的な結論を導く推論。","note":"演繹と対比して理解する。"}]},{"topic":"科学と人間","cards":[{"term":"人工知能（AI）","reading":"じんこうちのう","meaning":"人間の知的活動の一部を機械に担わせようとする技術の総称。","note":"人間とは何かを考える鏡として本文に登場する。"},{"term":"鏡としての人工知能","reading":"かがみとしてのじんこうちのう","meaning":"AIを通して逆に人間らしさが浮かび上がるという比喩的な捉え方。","note":"テーマ名にも関わる中心的な比喩。"},{"term":"ロボットと隣人","reading":"ろぼっととりんじん","meaning":"機械を単なる道具ではなく、共に暮らす存在として捉え直す視点。","note":"技術と人間の距離を考える論点。"},{"term":"人間らしさの条件","reading":"にんげんらしさのじょうけん","meaning":"感情や身体、他者との関係など、人間を人間たらしめる要素。","note":"AIと比較することで問い直される。"},{"term":"技術と倫理","reading":"ぎじゅつとりんり","meaning":"新しい技術をどう使うべきかという善悪や責任の問題。","note":"科学の進歩と切り離せないテーマ。"},{"term":"比喩の読み取り","reading":"ひゆのよみとり","meaning":"たとえが何と何を結び付けているかを読み解くこと。","note":"抽象的な評論を理解する手がかりになる。"}]},{"topic":"言葉と認識","cards":[{"term":"もの命名","reading":"ものめいめい","meaning":"対象に名前を与えることで、それを一つのものとして捉える働き。","note":"言葉が認識を作る出発点として扱われる。"},{"term":"言葉と認識","reading":"ことばとにんしき","meaning":"言葉を持つことで世界の見え方や分け方が変わるという関係。","note":"このテーマの中心的な問い。"},{"term":"パラダイム","reading":"ぱらだいむ","meaning":"ある時代や分野で共有される、物事の見方や考え方の枠組み。","note":"科学的発見の捉え方が変わる例で説明される。"},{"term":"科学的発見","reading":"かがくてきはっけん","meaning":"新しい事実や法則を見つけること。見方自体が変わる場合もある。","note":"命名や分類と結び付けて論じられる。"},{"term":"常識を疑う","reading":"じょうしきをうたがう","meaning":"当たり前とされる見方を一度立ち止まって確かめる姿勢。","note":"新しい認識を得るための出発点。"}]},{"topic":"知のゆくえと未来","cards":[{"term":"知識の作為性","reading":"ちしきのさくいせい","meaning":"知識は自然に与えられるのではなく、人が目的に応じて作り出す面があること。","note":"知を固定的に捉えないための視点。"},{"term":"知識の構造性","reading":"ちしきのこうぞうせい","meaning":"知識はばらばらではなく、互いに関連し合って体系をなしていること。","note":"個々の情報をつなげて理解する必要を示す。"},{"term":"もう一つの知性","reading":"もうひとつのちせい","meaning":"数値や論理だけでは測れない、別の形の賢さや理解のあり方。","note":"未来の知の姿を考えるキーワード。"},{"term":"サピエンス","reading":"さぴえんす","meaning":"現生人類を指す学名に由来する呼び方で、人類全体を表す語。","note":"人類の歴史と未来を論じる文脈で使われる。"},{"term":"未来のありか","reading":"みらいのありか","meaning":"知識や知性が今後どこへ向かうのかという問い。","note":"評論全体のまとめにつながる論点。"}]}]},{"subject":"文学国語","topics":[{"topic":"日本の近代文学の流れ","cards":[{"term":"言文一致","reading":"げんぶんいっち","meaning":"話し言葉と書き言葉を近づけようとした近代の文章改革の動き。","note":"近代文学成立の土台となった運動。"},{"term":"坪内逍遥","reading":"つぼうちしょうよう","meaning":"明治期の文学者で、写実的な小説の必要を説いた人物。","note":"代表的な理論書が近代小説論の出発点とされる。"},{"term":"写実主義","reading":"しゃじつしゅぎ","meaning":"現実をありのままに描こうとする文学の立場。リアリズムともいう。","note":"近代文学の流れの初期を代表する考え方。"},{"term":"ロマン主義","reading":"ろまんしゅぎ","meaning":"個人の感情や理想、美を重んじる文学の傾向。","note":"写実主義の後に広がった対照的な流れ。"},{"term":"自然主義","reading":"しぜんしゅぎ","meaning":"人間を自然や環境の産物として客観的に描こうとする傾向。","note":"明治末から大正初期に影響を持った。"},{"term":"白樺派","reading":"しらかばは","meaning":"雑誌『白樺』を中心に活動し、人道主義や理想主義を掲げた作家たちの集まり。","note":"自然主義への反動として位置づけられる。"}]},{"topic":"明治の作家たち","cards":[{"term":"夏目漱石","reading":"なつめそうせき","meaning":"『吾輩は猫である』『こころ』などで知られる明治・大正の代表的作家。","note":"このテーマと『こころ』のテーマの両方に関わる。"},{"term":"森鴎外","reading":"もりおうがい","meaning":"軍医でありながら『舞姫』などを書いた明治の作家。鴎外は号。","note":"『舞姫』の作者として押さえる。"},{"term":"樋口一葉","reading":"ひぐちいちよう","meaning":"『たけくらべ』で知られ、短い生涯で明治の女性の姿を描いた作家。","note":"明治を代表する女性作家。"},{"term":"島崎藤村","reading":"しまざきとうそん","meaning":"詩人として出発し、『破戒』で自然主義小説の代表作を残した作家。","note":"詩から小説へ移った経歴が特徴。"},{"term":"二葉亭四迷","reading":"ふたばていしめい","meaning":"言文一致体の小説『浮雲』を書いた明治初期の作家。","note":"近代小説の先駆者として位置づけられる。"},{"term":"国木田独歩","reading":"くにきだどっぽ","meaning":"自然や田園を愛し、短編小説で知られるロマン主義的な作家。","note":"自然主義への橋渡しとも評される。"}]},{"topic":"山月記","cards":[{"term":"李徴","reading":"りちょう","meaning":"『山月記』の主人公で、詩人として名を成せず虎になってしまう人物。","note":"物語の中心人物。名前の読みに注意する。"},{"term":"袁傪","reading":"えんさん","meaning":"李徴の旧友で、旅の途中で虎となった李徴の声を聞く人物。","note":"李徴の告白を聞く聞き手の役割を担う。"},{"term":"臆病な自尊心と尊大な羞恥心","reading":"おくびょうなじそんしんとそんだいなしゅうちしん","meaning":"自分を守りたい気持ちと、人前で恥をかくことを恐れる気持ちを表す作中の言葉。","note":"李徴が虎になった理由を自ら語る核心部分。"},{"term":"虎になるということ","reading":"とらになるということ","meaning":"人間としての理性や姿を失うことを象徴する出来事。","note":"自尊心の問題が姿を変える比喩として読む。"},{"term":"中島敦","reading":"なかじまあつし","meaning":"『山月記』の作者。中国の古典を題材にした作品で知られる。","note":"作者と作品をセットで覚える。"},{"term":"一人称の告白","reading":"いちにんしょうのこくはく","meaning":"登場人物が「私」の立場で自らの内面を語る形式。","note":"李徴の独白が物語の中心をなす。"}]},{"topic":"こころ","cards":[{"term":"先生","reading":"せんせい","meaning":"『こころ』の語り手である「私」が慕う年上の人物。","note":"作品の中心人物で、遺書の書き手でもある。"},{"term":"K","reading":"けー","meaning":"先生の友人で、先生と同じ女性を愛したことから悲劇につながる人物。","note":"イニシャルで呼ばれることが人物関係の特徴。"},{"term":"遺書","reading":"いしょ","meaning":"先生が「私」に宛てて残した長い手紙で、過去の秘密が明かされる部分。","note":"作品後半の中心をなす形式。"},{"term":"エゴイズム","reading":"えごいずむ","meaning":"自分の利益や気持ちを優先する自己中心的なあり方。","note":"先生の後悔を理解するキーワード。"},{"term":"明治の精神","reading":"めいじのせいしん","meaning":"明治という時代を生きた人々の生き方や価値観を象徴する言葉。","note":"先生の死の意味を考える手がかり。"},{"term":"夏目漱石","reading":"なつめそうせき","meaning":"『こころ』の作者。近代日本を代表する小説家。","note":"明治の作家たちとも重なる重要人物。"}]},{"topic":"大正・昭和の文学","cards":[{"term":"志賀直哉","reading":"しがなおや","meaning":"白樺派の中心作家で、『城の崎にて』などの心境小説で知られる。","note":"大正文学を代表する一人。"},{"term":"芥川龍之介","reading":"あくたがわりゅうのすけ","meaning":"『羅生門』『鼻』など短編の名手として知られる大正期の作家。","note":"古典を題材にした作品も多い。"},{"term":"プロレタリア文学","reading":"ぷろれたりあぶんがく","meaning":"労働者の生活や社会問題を描き、社会変革を目指した文学の動き。","note":"昭和初期に広がった社会派の流れ。"},{"term":"太宰治","reading":"だざいおさむ","meaning":"『人間失格』『走れメロス』で知られる昭和の作家。","note":"戦前戦後を通じて読まれる代表的作家。"},{"term":"川端康成","reading":"かわばたやすなり","meaning":"『雪国』などで日本的な美を描き、ノーベル文学賞を受けた作家。","note":"新感覚派から出発した経歴も押さえる。"},{"term":"三島由紀夫","reading":"みしまゆきお","meaning":"『金閣寺』などで知られ、美と行動を追求した昭和の作家。","note":"戦後文学を代表する一人。"}]},{"topic":"檸檬","cards":[{"term":"梶井基次郎","reading":"かじいもとじろう","meaning":"『檸檬』の作者。感覚的な描写に優れた短編を残した作家。","note":"作者と作品を結び付けて覚える。"},{"term":"えたいの知れない不快の塊","reading":"えたいのしれないふかいのかたまり","meaning":"主人公を苦しめる原因不明の憂鬱な気分を表す作中の表現。","note":"作品冒頭のキーワード。"},{"term":"檸檬","reading":"れもん","meaning":"主人公が果物店で買い、重みや冷たさに心を引かれる果物。","note":"作品の題名であり象徴的な品物。"},{"term":"丸善","reading":"まるぜん","meaning":"主人公が訪れる書店で、画集の上に檸檬を置く場面の舞台。","note":"結末の場面と結び付けて覚える。"},{"term":"感覚の描写","reading":"かんかくのびょうしゃ","meaning":"色や重さ、冷たさなど五感を通した表現の仕方。","note":"梶井の作風を特徴づける要素。"},{"term":"爆弾の比喩","reading":"ばくだんのひゆ","meaning":"置いた檸檬を爆弾に見立てて想像する主人公の空想。","note":"憂鬱を吹き飛ばしたい気持ちの表れと読む。"}]},{"topic":"舞姫","cards":[{"term":"森鷗外","reading":"もりおうがい","meaning":"『舞姫』の作者。ドイツ留学の経験を持つ軍医・作家。","note":"作中では「鴎外」と表記される場合もある。"},{"term":"太田豊太郎","reading":"おおたとよたろう","meaning":"『舞姫』の主人公で、ドイツへ留学した官僚。手記形式で物語を語る。","note":"エリスとの関係と帰国の決断が中心になる。"},{"term":"エリス","reading":"えりす","meaning":"ベルリンで豊太郎と出会う踊り子の女性。","note":"豊太郎の生き方を揺るがす人物。"},{"term":"相沢謙吉","reading":"あいざわけんきち","meaning":"豊太郎の友人で、帰国をめぐる決断に関わる人物。","note":"主人公の選択に影響を与える存在。"},{"term":"文語体","reading":"ぶんごたい","meaning":"昔の書き言葉の文体で書かれていること。","note":"明治初期の作品の特徴として押さえる。"},{"term":"近代の自我","reading":"きんだいのじが","meaning":"自分の意志で生き方を選ぼうとする近代的な意識。","note":"豊太郎の迷いを通して描かれる主題。"}]},{"topic":"随筆を読む","cards":[{"term":"随筆（エッセイ）","reading":"ずいひつ（えっせい）","meaning":"体験や見聞をもとに、感想や考えを自由な形式で書いた文章。","note":"小説との違いを意識して読むジャンル。"},{"term":"書き手の視点","reading":"かきてのしてん","meaning":"書き手が何に注目し、どう感じているかという見方の位置。","note":"随筆では書き手自身の感じ方が中心になる。"},{"term":"体験と感想","reading":"たいけんとかんそう","meaning":"実際に経験した出来事と、それに対する気持ちや考えの組み合わせ。","note":"随筆の基本的な構成要素。"},{"term":"国語から旅立って","reading":"こくごからたびたって","meaning":"教科書に収められた随筆作品の題名の一つ。","note":"随筆を読むテーマで扱う教材名として覚える。"},{"term":"クレールという女","reading":"くれーるというおんな","meaning":"教科書に収められた随筆作品に登場する人物名を含む題材。","note":"教材の内容を区別するための目印。"},{"term":"光の窓","reading":"ひかりのまど","meaning":"教科書に収められた随筆作品の題名の一つ。","note":"随筆教材の一つとして位置づけられる。"}]},{"topic":"戯曲―父と暮せば","cards":[{"term":"戯曲","reading":"ぎきょく","meaning":"舞台で上演するために書かれた作品。台詞とト書きで構成される。","note":"小説と違い、演じられることを前提とする形式。"},{"term":"井上ひさし","reading":"いのうえひさし","meaning":"『父と暮せば』の作者。劇作家・小説家として知られる。","note":"原爆を題材にした作品群でも知られる。"},{"term":"美津江","reading":"みつえ","meaning":"『父と暮せば』の主人公で、原爆で父を失いながら生きる女性。","note":"父との対話を通して心の変化が描かれる。"},{"term":"竹造","reading":"たけぞう","meaning":"美津江の父で、亡霊として娘の前に現れる人物。","note":"娘を励ます役割を担う。"},{"term":"ト書き","reading":"とがき","meaning":"台詞以外の、場面や動作、心理などを指示する地の文。","note":"戯曲特有の要素として小説の地の文と区別する。"},{"term":"原爆文学","reading":"げんばくぶんがく","meaning":"原爆の被害や体験を題材にした文学の総称。","note":"『父と暮せば』が分類される分野。"}]},{"topic":"詩・短歌・俳句","cards":[{"term":"短歌","reading":"たんか","meaning":"五・七・五・七・七の三十一音で作る日本の定型詩。","note":"俳句との音数の違いで区別する。"},{"term":"俳句","reading":"はいく","meaning":"五・七・五の十七音で作り、原則として季語を含む短い詩。","note":"世界で最も短い詩型の一つとされる。"},{"term":"季語","reading":"きご","meaning":"季節を表す決まった言葉で、俳句に季節感を与える要素。","note":"歳時記にまとめられている。"},{"term":"与謝野晶子","reading":"よさのあきこ","meaning":"明治期の歌人で、情熱的な歌集『みだれ髪』で知られる。","note":"短歌革新の代表的人物。"},{"term":"正岡子規","reading":"まさおかしき","meaning":"俳句や短歌の革新を進めた明治期の文学者。","note":"写生の考え方を広めた人物。"},{"term":"口語詩","reading":"こうごし","meaning":"日常の話し言葉で書かれた近代以降の詩。","note":"文語詩との対比で理解する。"}]},{"topic":"古典文学の基礎","cards":[{"term":"源氏物語","reading":"げんじものがたり","meaning":"平安時代に紫式部が書いた長編物語で、光源氏を中心に描く。","note":"王朝文学の代表作。"},{"term":"枕草子","reading":"まくらのそうし","meaning":"平安時代に清少納言が書いた随筆で、「をかし」の美意識で知られる。","note":"随筆文学の代表作として徒然草と比べられる。"},{"term":"竹取物語","reading":"たけとりものがたり","meaning":"かぐや姫の物語で、現存する最古の物語文学とされる作品。","note":"物語の祖と呼ばれる位置づけ。"},{"term":"平家物語","reading":"へいけものがたり","meaning":"平家の興亡を描いた軍記物語で、琵琶法師によって語り広められた。","note":"「無常」の主題で知られる。"},{"term":"徒然草","reading":"つれづれぐさ","meaning":"鎌倉時代に兼好法師が書いた随筆集。","note":"枕草子・方丈記と並ぶ三大随筆の一つ。"},{"term":"万葉集","reading":"まんようしゅう","meaning":"奈良時代に編まれた現存最古の歌集で、幅広い身分の歌が収められる。","note":"和歌の原点として位置づけられる。"}]}]},{"subject":"日本史","topics":[{"topic":"縄文・弥生時代","cards":[{"term":"縄文土器","reading":"じょうもんどき","meaning":"表面に縄目の文様をつけた土器で、煮炊きや貯蔵に使われた。厚手で多様な形がある。","note":"約1万年続いた縄文時代を代表する道具で、狩猟・採集生活の定着を示す。"},{"term":"貝塚","reading":"かいづか","meaning":"食べた貝の殻や骨などを捨てた場所が積み重なった遺跡。生活の様子を知る手がかりになる。","note":"食生活や道具が分かるため、当時の暮らしを復元する手がかりになる。"},{"term":"三内丸山遺跡","reading":"さんないまるやまいせき","meaning":"青森県にある縄文時代の大規模な集落跡。大きな建物の柱穴や多くの出土品が見つかった。","note":"縄文社会が想像以上に大規模で計画的だったことを示す遺跡。"},{"term":"弥生土器","reading":"やよいどき","meaning":"薄手で赤褐色の、縄文土器よりすっきりした形の土器。稲作とともに広がった。","note":"弥生時代の始まりを示し、高床倉庫などとともに農耕社会を表す。"},{"term":"稲作の伝来","reading":"いなさくのでんらい","meaning":"大陸から水田で米を作る技術が伝わり、日本列島に広がった出来事。","note":"定住と余剰生産を生み、ムラからクニへ社会が変わる出発点になった。"},{"term":"吉野ヶ里遺跡","reading":"よしのがりいせき","meaning":"佐賀県にある弥生時代の環濠集落跡。物見やぐらや墳丘墓が復元されている。","note":"防御を備えた大集落として、弥生時代の争いと社会のまとまりを示す。"},{"term":"邪馬台国","reading":"やまたいこく","meaning":"3世紀ごろ、女王卑弥呼が治めたと中国の史書に記された国。所在地は論争が続く。","note":"魏に使いを送った記録があり、初期の国家形成を考える中心テーマ。"}]},{"topic":"飛鳥・奈良時代と律令国家","cards":[{"term":"聖徳太子（厩戸皇子）","reading":"しょうとくたいし（うまやどのおうじ）","meaning":"推古天皇のもとで政治を行い、冠位十二階や十七条の憲法を定めたとされる皇族。","note":"天皇中心の国家づくりを進めた飛鳥時代の中心人物。"},{"term":"大化の改新","reading":"たいかのかいしん","meaning":"645年に中大兄皇子らが蘇我氏を倒し、公地公民などを掲げた一連の改革。","note":"律令国家への歩みが始まった転換点として扱われる。"},{"term":"律令","reading":"りつりょう","meaning":"律は刑罰、令は行政などの決まりをまとめた法体系。中国の制度を手本にした。","note":"中央集権的な国家運営の土台となり、班田収授や税制を支えた。"},{"term":"班田収授法","reading":"はんでんしゅうじゅほう","meaning":"戸籍に基づき6歳以上の人々に口分田を与え、死後に返させる制度。","note":"公地公民を具体化し、租を集めるための土地制度だった。"},{"term":"租・調・庸","reading":"そ・ちょう・よう","meaning":"租は稲、調は特産物、庸は労役の代わりの布などを納める税の組み合わせ。","note":"律令制の税制の柱で、農民の負担の重さを示す。"},{"term":"天平文化","reading":"てんぴょうぶんか","meaning":"奈良時代、唐や西域の影響を受けた国際色豊かな文化。正倉院宝物にその姿が残る。","note":"仏教を中心に栄え、東大寺の大仏造立とも結びつく。"}]},{"topic":"平安時代と摂関政治","cards":[{"term":"平安遷都","reading":"へいあんせんと","meaning":"794年に桓武天皇が都を平安京へ移したこと。","note":"奈良時代から平安時代へ移る区切りで、約400年続く都の始まり。"},{"term":"摂関政治","reading":"せっかんせいじ","meaning":"藤原氏が幼い天皇の摂政や成年の関白となり、実権を握った政治の形。","note":"藤原道長の時期に最盛期を迎えた貴族政治の特徴。"},{"term":"藤原道長","reading":"ふじわらのみちなが","meaning":"摂関政治の全盛期を築いた藤原氏の人物。娘たちを天皇の后とした。","note":"『この世をば』で知られ、御堂関白と呼ばれた権力者。"},{"term":"国風文化","reading":"こくふうぶんか","meaning":"唐との交流が弱まる中で、日本の風土に合った貴族文化が育った平安中期の文化。","note":"かな文字や和歌、寝殿造など日本的な表現が広がった時期。"},{"term":"かな文字","reading":"かなもじ","meaning":"漢字の音を借りたり崩したりして作られた、ひらがな・カタカナのもとになる文字。","note":"女性の文学を支え、国風文化の成立に大きく関わった。"},{"term":"源氏物語と枕草子","reading":"げんじものがたりとまくらのそうし","meaning":"紫式部と清少納言による平安貴族社会を描いた代表的な文学作品。","note":"かな文学の頂点として、国風文化を象徴する組み合わせ。"}]},{"topic":"鎌倉幕府と武士の社会","cards":[{"term":"源頼朝","reading":"みなもとのよりとも","meaning":"平氏を倒し、鎌倉に幕府を開いて初代将軍となった武士の棟梁。","note":"武家政権を全国的な仕組みにした鎌倉時代の創始者。"},{"term":"守護・地頭","reading":"しゅご・じとう","meaning":"守護は国ごとの治安や軍事、地頭は荘園・公領の管理を担った幕府の役職。","note":"幕府が全国を支配するための両輪となった制度。"},{"term":"御恩と奉公","reading":"ごおんとほうこう","meaning":"将軍が土地などを与え、御家人が軍役などで応える主従関係の結びつき。","note":"鎌倉武士社会の土台で、土地を通じた結びつきが特徴。"},{"term":"執権政治","reading":"しっけんせいじ","meaning":"将軍を補佐する執権の北条氏が幕府の実権を握った政治。","note":"北条泰時らが御成敗式目を定め、武家法を整えた時期。"},{"term":"元寇","reading":"げんこう","meaning":"13世紀後半、元が二度にわたり日本へ攻めてきた出来事。文永・弘安の役という。","note":"御家人の負担を増やし、幕府の力を弱める要因の一つになった。"},{"term":"御成敗式目","reading":"ごせいばいしきもく","meaning":"1232年に定められた、武家社会の慣習をもとにした最初の武家法。","note":"裁判の基準を明らかにし、後の武家法の基礎になった。"}]},{"topic":"室町時代と戦国への歩み","cards":[{"term":"足利尊氏と室町幕府","reading":"あしかがたかうじとむろまちばくふ","meaning":"尊氏が京都に開いた武家政権。幕府の所在地が室町に移ったことから名がついた。","note":"鎌倉幕府滅亡後の新たな武家政権として室町時代を開いた。"},{"term":"南北朝の動乱","reading":"なんぼくちょうのどうらん","meaning":"天皇家が南朝と北朝に分かれて争った14世紀の内乱状態。","note":"幕府と朝廷の関係を揺るがし、地方の武士の力を高めた。"},{"term":"足利義満と日明貿易","reading":"あしかがよしみつとにちみんぼうえき","meaning":"義満が明との正式な貿易を始め、勘合を用いて倭寇と区別した交易。","note":"金閣の北山文化を支える富をもたらした外交・貿易。"},{"term":"応仁の乱","reading":"おうにんのらん","meaning":"1467年に始まった、将軍家の継承と有力大名の対立が重なった内乱。","note":"幕府の権威を大きく落とし、戦国時代へ進むきっかけになった。"},{"term":"下剋上","reading":"げこくじょう","meaning":"身分の低い者が実力で上の者を倒し、成り上がる風潮や出来事。","note":"戦国大名の登場を象徴する、室町後期の社会の動き。"},{"term":"東山文化","reading":"ひがしやまぶんか","meaning":"足利義政のもと、銀閣や書院造、茶の湯など落ち着いた美意識が育った文化。","note":"現在の和室や侘びの感覚につながる室町後期の文化。"}]},{"topic":"戦国時代と織田・豊臣","cards":[{"term":"織田信長","reading":"おだのぶなが","meaning":"尾張から勢力を広げ、室町幕府を滅ぼして天下統一に近づいた戦国大名。","note":"革新的な政策で知られ、豊臣秀吉へ統一事業が引き継がれた。"},{"term":"楽市・楽座","reading":"らくいち・らくざ","meaning":"市場の税を免じたり座の特権を廃したりして、商工業の自由を促した政策。","note":"信長が城下町の発展を狙って進めた経済政策。"},{"term":"豊臣秀吉","reading":"とよとみひでよし","meaning":"信長の後を継ぎ、全国統一を果たした武将。農民出身から関白に上りつめた。","note":"太閤検地と刀狩で兵農分離を進めた統一政権の中心。"},{"term":"太閤検地","reading":"たいこうけんち","meaning":"全国の田畑を測り、収穫量を石高で表して耕作者を登録した土地調査。","note":"石高制の基礎となり、年貢徴収と身分統制を強めた。"},{"term":"刀狩","reading":"かたながり","meaning":"農民から刀などの武器を取り上げ、農業に専念させた政策。","note":"一揆を防ぎ、武士と農民を分ける兵農分離を進めた。"},{"term":"長篠の戦い","reading":"ながしののたたかい","meaning":"1575年、織田・徳川連合軍が武田軍を破った合戦。鉄砲の活用で知られる。","note":"戦国時代の戦い方と勢力図を変えた出来事として扱われる。"}]},{"topic":"江戸幕府の成立","cards":[{"term":"徳川家康","reading":"とくがわいえやす","meaning":"関ヶ原の戦いに勝ち、江戸に幕府を開いた初代将軍。","note":"約260年続く江戸幕府の仕組みの出発点を作った人物。"},{"term":"関ヶ原の戦い","reading":"せきがはらのたたかい","meaning":"1600年、家康率いる東軍が石田三成らの西軍を破った天下分け目の合戦。","note":"徳川氏による支配が決定的になり、幕府成立へつながった。"},{"term":"大坂の陣","reading":"おおさかのじん","meaning":"1614〜15年、幕府が豊臣氏を滅ぼした戦い。冬の陣と夏の陣がある。","note":"豊臣氏の滅亡で、徳川政権への大きな対抗勢力が消えた。"},{"term":"武家諸法度","reading":"ぶけしょはっと","meaning":"大名を統制するために幕府が出した法令。城の修理や婚姻などに制限をかけた。","note":"参勤交代の義務づけなど、幕藩体制を固める道具になった。"},{"term":"参勤交代","reading":"さんきんこうたい","meaning":"大名が江戸と領地を1年おきに行き来し、妻子を江戸に住まわせた制度。","note":"大名の財政負担と江戸の発展を生んだ江戸時代の代表制度。"},{"term":"鎖国","reading":"さこく","meaning":"対外関係を長崎など限られた窓口に絞り、キリスト教を厳しく取り締まった体制。","note":"近年は『鎖国』という言葉より、限定的な外交管理として理解される。"}]},{"topic":"江戸時代の社会と改革","cards":[{"term":"身分制度","reading":"みぶんせいど","meaning":"武士・百姓・町人などに人々を分け、職業や暮らしを規制した江戸時代の秩序。","note":"幕藩体制を支えたが、実際には身分を越えた動きもあった。"},{"term":"村請制と五人組","reading":"むらうけせいとごにんぐみ","meaning":"村全体で年貢を請け負い、5戸ほどの組で互いに責任を持たせた仕組み。","note":"農村統制の基本で、年貢の確保と治安維持に使われた。"},{"term":"享保の改革","reading":"きょうほうのかいかく","meaning":"8代将軍徳川吉宗が財政再建や目安箱の設置などを進めた改革。","note":"三大改革の最初で、質素倹約と新田開発が柱だった。"},{"term":"田沼意次と寛政の改革","reading":"たぬまおきつぐとかんせいのかいかく","meaning":"商業を重視した田沼の政治の後、松平定信が厳しい引き締めを行った改革。","note":"経済政策の方向が正反対に振れた対比で覚えるテーマ。"},{"term":"天保の改革","reading":"てんぽうのかいかく","meaning":"水野忠邦が倹約令や人返し令などを出した、江戸幕府最後の大きな改革。","note":"三大改革の一つだが、効果は限られ幕府の衰えが目立った。"},{"term":"化政文化","reading":"かせいぶんか","meaning":"江戸を中心に町人の好みを反映した文学・浮世絵などが栄えた文化。","note":"元禄文化と並ぶ江戸文化の山で、庶民の広がりが特徴。"}]},{"topic":"明治維新","cards":[{"term":"ペリー来航","reading":"ぺりーらいこう","meaning":"1853年、アメリカのペリーが浦賀に来て開国を求めた出来事。","note":"幕末の動揺を決定的にし、開国と維新への流れを加速させた。"},{"term":"日米和親条約","reading":"にちべいわしんじょうやく","meaning":"1854年に結ばれた、下田と箱館を開くなどした日本とアメリカの条約。","note":"鎖国体制が崩れる第一歩となった条約。"},{"term":"大政奉還","reading":"たいせいほうかん","meaning":"1867年、徳川慶喜が政権を朝廷へ返したこと。","note":"江戸幕府が終わり、明治政府樹立へ進む区切りになった。"},{"term":"廃藩置県","reading":"はいはんちけん","meaning":"藩を廃して県を置き、知藩事を免じて中央から府知事・県令を送った改革。","note":"中央集権国家を作るための明治初期の大きな一歩。"},{"term":"地租改正","reading":"ちそかいせい","meaning":"土地の価格の3％を現金で納めさせる税制改革。地券を発行した。","note":"政府の安定した収入源となり、近代的な土地所有を進めた。"},{"term":"殖産興業","reading":"しょくさんこうぎょう","meaning":"官営工場の設立などで産業を育て、国を富ませようとした政策。","note":"富国強兵と並ぶ明治政府の基本方針の一つ。"}]},{"topic":"立憲政治と日清・日露戦争","cards":[{"term":"大日本帝国憲法","reading":"だいにっぽんていこくけんぽう","meaning":"1889年発布の、天皇が定める欽定憲法。プロイセンの憲法を参考にした。","note":"帝国議会開設とともに立憲政治の枠組みを作った。"},{"term":"帝国議会","reading":"ていこくぎかい","meaning":"貴族院と衆議院からなる議会。1890年に初めて開かれた。","note":"予算審議などを通じ、政党が力を伸ばす舞台になった。"},{"term":"条約改正","reading":"じょうやくかいせい","meaning":"幕末に結んだ不平等条約を改め、関税自主権や領事裁判権の問題を解消する取り組み。","note":"陸奥宗光と小村寿太郎の時期に段階的に達成された外交課題。"},{"term":"日清戦争","reading":"にっしんせんそう","meaning":"1894〜95年、朝鮮をめぐり日本と清が戦った戦争。下関条約で決着した。","note":"遼東半島などを得たが三国干渉を受け、対露意識が高まった。"},{"term":"日露戦争","reading":"にちろせんそう","meaning":"1904〜05年、満洲と朝鮮をめぐる日本とロシアの戦争。ポーツマス条約で終わった。","note":"日本の勝利はアジア諸国に影響を与えた一方、国民の負担も大きかった。"},{"term":"産業革命の進展","reading":"さんぎょうかくめいのしんてん","meaning":"日清戦争前後から軽工業、日露戦争前後から重工業で機械制生産が広がった動き。","note":"紡績から製鉄へと広がり、日本の資本主義の土台ができた。"}]},{"topic":"大正デモクラシーと両大戦間期","cards":[{"term":"大正デモクラシー","reading":"たいしょうでもくらしー","meaning":"大正期に広がった民主主義や自由主義を求める風潮。吉野作造の民本主義が知られる。","note":"政党政治や普通選挙運動、社会運動の高まりと結びつく。"},{"term":"政党内閣","reading":"せいとうないかく","meaning":"衆議院の多数党をもとに内閣が作られる政治の形。原敬内閣が本格的な始まりとされる。","note":"大正から昭和初期に定着したが、1932年に途絶えた。"},{"term":"普通選挙法","reading":"ふつうせんきょほう","meaning":"1925年、25歳以上の男性すべてに選挙権を与えた法律。","note":"納税資格が外れた一方、同時に治安維持法も制定された。"},{"term":"治安維持法","reading":"ちあんいじほう","meaning":"社会主義運動などを取り締まるために1925年に制定された法律。","note":"言論や思想への統制を強める道具として拡大されていった。"},{"term":"世界恐慌","reading":"せかいきょうこう","meaning":"1929年にアメリカから始まった世界的な経済不況。","note":"日本でも昭和恐慌が起こり、農村の困窮や軍部の台頭につながった。"},{"term":"大衆文化の広がり","reading":"たいしゅうぶんかのひろがり","meaning":"ラジオや映画、雑誌などが都市の人々の日常に入り込んだ大正・昭和初期の変化。","note":"生活様式の近代化を示し、モダンな文化が広がった。"}]},{"topic":"太平洋戦争と戦後","cards":[{"term":"太平洋戦争","reading":"たいへいようせんそう","meaning":"1941年の真珠湾攻撃に始まり、アジア・太平洋で広がった戦争。","note":"日中戦争から続く十五年戦争の後半として位置づけられる。"},{"term":"ポツダム宣言","reading":"ぽつだむせんげん","meaning":"1945年、連合国が日本に降伏を求めて出した宣言。日本はこれを受諾した。","note":"戦争終結と占領政策の出発点になった文書。"},{"term":"日本国憲法","reading":"にっぽんこくけんぽう","meaning":"国民主権・平和主義・基本的人権の尊重を柱とする戦後の憲法。1947年施行。","note":"戦後民主主義の土台となり、大日本帝国憲法と対比される。"},{"term":"農地改革","reading":"のうちかいかく","meaning":"地主の土地を政府が買い上げ、小作農に安く売り渡して自作農を増やした改革。","note":"戦後改革の一つで、農村の民主化を進めた。"},{"term":"サンフランシスコ平和条約","reading":"さんふらんしすこへいわじょうやく","meaning":"1951年に結ばれ、日本が独立を回復する根拠となった講和条約。","note":"同時に日米安全保障条約も結ばれ、戦後の国際関係の枠ができた。"},{"term":"高度経済成長","reading":"こうどけいざいせいちょう","meaning":"1950年代半ばから1970年代初めまで、経済が急速に拡大した時期。","note":"生活水準が大きく変わり、公害問題も深刻化した時代。"}]},{"topic":"戦後の復興と高度経済成長","cards":[{"term":"朝鮮戦争と特需","reading":"ちょうせんせんそうととくじゅ","meaning":"朝鮮戦争の際に米軍などからの注文が増え、日本経済が活気づいたこと。","note":"占領期の日本が復興へ向かう追い風になった出来事。"},{"term":"三種の神器と3C","reading":"さんしゅのじんぎとすりーしー","meaning":"高度成長期に憧れの品とされた電化製品や、カラーテレビ・クーラー・自動車の総称。","note":"豊かさの象徴として、生活の変化を表す言葉。"},{"term":"公害問題","reading":"こうがいもんだい","meaning":"工場排水や排煙などが健康被害や環境破壊を引き起こした問題。水俣病などが知られる。","note":"成長の影の部分として、公害対策基本法などの対応を促した。"},{"term":"石油危機（オイルショック）","reading":"せきゆきき（おいるしょっく）","meaning":"1973年などに石油価格が急騰し、物価上昇や混乱を招いた出来事。","note":"高度経済成長が終わるきっかけとなり、省エネが進んだ。"},{"term":"日米安全保障条約","reading":"にちべいあんぜんほしょうじょうやく","meaning":"日本とアメリカの軍事的な協力関係を定めた条約。平和条約と同時に結ばれた。","note":"戦後日本の外交・安全保障の軸となった仕組み。"}]}]},{"subject":"世界史","topics":[{"topic":"古代文明の出現","cards":[{"term":"農耕の始まり","reading":"のうこうのはじまり","meaning":"西アジアなどで植物の栽培と動物の飼育が始まり、食料生産が可能になった変化。","note":"定住生活と人口増加を招き、文明が生まれる前提になった。"},{"term":"メソポタミア文明","reading":"めそぽたみあぶんめい","meaning":"ティグリス・ユーフラテス川の間で栄えた文明。楔形文字や法典で知られる。","note":"都市国家が争いながら発展した、最も古い文明の一つ。"},{"term":"エジプト文明","reading":"えじぷとぶんめい","meaning":"ナイル川の定期的な氾濫を利用して栄えた文明。ピラミッドや神聖文字が残る。","note":"ファラオを中心とする統一国家が長く続いたことが特徴。"},{"term":"インダス文明","reading":"いんだすぶんめい","meaning":"インダス川流域に計画的な都市が作られた文明。モヘンジョ＝ダロが代表的。","note":"排水設備を備えた都市設計の高さで知られる。"},{"term":"黄河文明と殷","reading":"こうがぶんめいといん","meaning":"黄河流域で生まれた中国最古級の文明と、甲骨文字を使った殷王朝。","note":"漢字のもとになる文字や青銅器文化が発達した。"},{"term":"文明の共通点","reading":"ぶんめいのきょうつうてん","meaning":"大河の近くで農耕が進み、都市・文字・金属器・身分社会などが現れた点。","note":"各地の古代文明を比べるときの基本的な視点になる。"}]},{"topic":"古代ギリシャとローマ","cards":[{"term":"ポリス","reading":"ぽりす","meaning":"古代ギリシャの都市を中心とする独立した小さな国家の形。","note":"アテネやスパルタなど、それぞれ制度や文化が異なった。"},{"term":"アテネの民主政","reading":"あてねのみんしゅせい","meaning":"成人男性市民が民会に参加して政治を決めたアテネの仕組み。","note":"女性や奴隷は除かれたが、民主政の起源として重要。"},{"term":"ペルシア戦争","reading":"ぺるしあせんそう","meaning":"ギリシャのポリス連合がアケメネス朝ペルシアの侵攻を退けた戦争。","note":"ポリスの結束を強めたが、その後の対立の背景にもなった。"},{"term":"アレクサンドロス大王","reading":"あれくさんどろすだいおう","meaning":"マケドニアの王としてペルシアを滅ぼし、インド西部まで遠征した人物。","note":"ヘレニズム文化が広がるきっかけを作った。"},{"term":"ローマ帝国","reading":"ろーまていこく","meaning":"地中海世界を統一した大帝国。法や道路、都市施設を各地に広げた。","note":"共和政から帝政へ移り、長い支配の仕組みを残した。"},{"term":"パクス・ロマーナ","reading":"ぱくす・ろまーな","meaning":"ローマの力によって地中海世界に平和が保たれたとされる時期。","note":"『ローマの平和』を意味し、交通や交易の発展と結びつく。"}]},{"topic":"イスラーム世界の成立と拡大","cards":[{"term":"ムハンマド","reading":"むはんまど","meaning":"イスラーム教の預言者とされ、メッカからメディナへ移住して共同体を作った人物。","note":"622年のヒジュラがイスラーム暦の起点になった。"},{"term":"コーランと六信五行","reading":"こーらんとろくしんごぎょう","meaning":"聖典コーランと、信じるべき事柄や実践すべき行いを示す教えの枠組み。","note":"イスラーム教徒の生活の基準として位置づけられる。"},{"term":"カリフ","reading":"かりふ","meaning":"預言者の後継者としてイスラーム共同体を率いた指導者の称号。","note":"政治と宗教の指導者を兼ねる存在として帝国を治めた。"},{"term":"ウマイヤ朝","reading":"うまいやちょう","meaning":"ダマスカスを都とし、イベリア半島まで勢力を広げたイスラーム王朝。","note":"急速な拡大の時期を担い、アラブ人の優位が特徴とされる。"},{"term":"アッバース朝","reading":"あっばーすちょう","meaning":"バグダードを都に、民族を越えたイスラーム帝国を築いた王朝。","note":"学問や交易が栄え、イスラーム文化の黄金期とされる。"},{"term":"拡大の背景","reading":"かくだいのはいけい","meaning":"交易路の掌握や周辺帝国の衰え、共同体のまとまりなどが重なった広がりの要因。","note":"短期間に広大な地域へ広がった理由を説明する視点。"}]},{"topic":"南アジアと東南アジアの世界","cards":[{"term":"グプタ朝","reading":"ぐぷたちょう","meaning":"4〜6世紀に北インドを統一した王朝。サンスクリット文化が栄えた。","note":"ゼロの概念や古典文化の発展で知られる時期。"},{"term":"ヒンドゥー教の形成","reading":"ひんどぅーきょうのけいせい","meaning":"バラモン教が民衆信仰と結びつき、カーストと結びついた宗教として整った過程。","note":"南アジア社会の土台となり、東南アジアへも伝わった。"},{"term":"デリー＝スルタン朝","reading":"でりー＝するたんちょう","meaning":"13世紀初め、デリーを拠点に北インドを支配したイスラーム王朝の総称。","note":"インドにイスラーム政権が根づく転換点になった。"},{"term":"シュリーヴィジャヤ","reading":"しゅりーゔぃじゃや","meaning":"スマトラ島を中心にマラッカ海峡の交易を押さえて栄えた港市国家。","note":"海の道の要衝を支配した東南アジアの代表例。"},{"term":"アンコール朝","reading":"あんこーるちょう","meaning":"カンボジアでアンコール＝ワットなどを築いた王朝。","note":"灌漑を基盤に繁栄した内陸型国家の代表例。"},{"term":"海の道と交易","reading":"うみのみちとこうえき","meaning":"インド洋や南シナ海を結ぶ海上交易路を通じた香辛料などの取引。","note":"東南アジアの国家形成と文化交流を促した仕組み。"}]},{"topic":"中国の王朝","cards":[{"term":"始皇帝","reading":"しこうてい","meaning":"秦の王として中国を統一し、初めて皇帝の称号を用いた人物。","note":"郡県制や文字・度量衡の統一など中央集権を進めた。"},{"term":"漢","reading":"かん","meaning":"秦の後に中国を統一した王朝。前漢と後漢に分かれる。","note":"儒教の重視やシルクロード交易など、長期王朝の原型を作った。"},{"term":"唐","reading":"とう","meaning":"隋の後に中国を統一し、東アジアに大きな影響を与えた王朝。","note":"律令制や長安の国際性が、日本の制度・文化にも影響した。"},{"term":"科挙","reading":"かきょ","meaning":"試験で官僚を登用する制度。隋で始まり唐以降に整えられた。","note":"家柄より学識を問う仕組みとして中国政治の特徴になった。"},{"term":"元","reading":"げん","meaning":"モンゴル系のフビライが建て、中国全土を支配した王朝。国号は大元。","note":"ユーラシア規模の交流の中で中国を治めた王朝。"},{"term":"清","reading":"しん","meaning":"満洲族が建て、中国を支配した最後の王朝。","note":"最大級の版図を持ったが、近代に欧米列強と向き合うことになった。"}]},{"topic":"モンゴル帝国とユーラシア","cards":[{"term":"チンギス＝ハン","reading":"ちんぎす＝はん","meaning":"モンゴル高原の諸部族を統一し、大帝国の基礎を築いた指導者。","note":"1206年の統一がモンゴル帝国拡大の出発点になった。"},{"term":"モンゴル帝国の拡大","reading":"もんごるていこくのかくだい","meaning":"騎馬軍団の機動力でユーラシア大陸の広い範囲を征服した動き。","note":"東西を結ぶ交通と交易が活発になる前提を作った。"},{"term":"4ハン国","reading":"よんはんこく","meaning":"帝国が分かれて成立したキプチャクなど四つのハン国の総称。","note":"分裂後も緩やかにつながり、地域ごとに異なる道を歩んだ。"},{"term":"元（フビライ）","reading":"げん（ふびらい）","meaning":"チンギスの孫フビライが南宋を滅ぼし、中国を支配した政権。","note":"日本への遠征を行い、日本史の元寇と直接つながる。"},{"term":"元の日本遠征","reading":"げんのにほんえんせい","meaning":"1274年と1281年に元が高麗軍などとともに日本へ攻めてきた出来事。","note":"モンゴルの拡大が東アジアの島国にまで及んだ例。"},{"term":"ユーラシアの交流","reading":"ゆーらじあのこうりゅう","meaning":"モンゴルの支配下で駅伝制などが整い、人や物、技術が大陸を横断した動き。","note":"マルコ＝ポーロの旅行記などを通じヨーロッパにも伝わった。"}]},{"topic":"ルネサンスと大航海時代","cards":[{"term":"ルネサンス","reading":"るねさんす","meaning":"古代ギリシャ・ローマの文化を見直し、人間らしい生き方を重んじた文化運動。","note":"イタリアから広がり、芸術や学問の新しい流れを作った。"},{"term":"レオナルド・ダ・ヴィンチ","reading":"れおなるど・だ・ゔぃんち","meaning":"絵画だけでなく解剖や機械の研究も行ったルネサンスを代表する人物。","note":"『モナ＝リザ』などで知られる万能の天才とされる。"},{"term":"宗教改革","reading":"しゅうきょうかいかく","meaning":"カトリック教会のあり方を批判し、プロテスタント諸派が生まれた16世紀の運動。","note":"ルターの主張から広がり、ヨーロッパの政治にも影響した。"},{"term":"コロンブス","reading":"ころんぶす","meaning":"1492年に大西洋を渡り、アメリカ大陸の島々に到達した航海者。","note":"ヨーロッパとアメリカ大陸の本格的な接触の始まりとされる。"},{"term":"マゼラン","reading":"まぜらん","meaning":"世界一周航海を始めた航海者。本人は途中で亡くなったが船隊が一周を果たした。","note":"地球規模の航海が可能になったことを示した航海。"},{"term":"バスコ・ダ・ガマ","reading":"ばすこ・だ・がま","meaning":"アフリカ南端を回ってインドへ至る航路を開いたポルトガルの航海者。","note":"香辛料貿易の主導権をヨーロッパ側が握る転機になった。"}]},{"topic":"主権国家体制と宗教改革","cards":[{"term":"ルターの宗教改革","reading":"るたーのしゅうきょうかいかく","meaning":"ルターが免罪符販売を批判し、聖書中心の信仰を訴えた改革の始まり。","note":"95か条の論題がきっかけとなり、プロテスタントが生まれた。"},{"term":"カルヴァンと予定説","reading":"かるゔぁんとよていせつ","meaning":"救われるかどうかはあらかじめ決まっているとするカルヴァンの教え。","note":"勤勉な職業生活を重んじる倫理と結びついて広がった。"},{"term":"イギリス国教会","reading":"いぎりすこっきょうかい","meaning":"国王を首長としてローマ教皇から離れたイギリスの教会組織。","note":"ヘンリ8世の離婚問題を契機に成立した国教会。"},{"term":"対抗宗教改革","reading":"たいこうしゅうきょうかいかく","meaning":"カトリック側が自己改革とプロテスタントへの反撃を進めた動き。","note":"トリエント公会議やイエズス会の活動が代表例。"},{"term":"三十年戦争","reading":"さんじゅうねんせんそう","meaning":"神聖ローマ帝国を舞台に宗教対立と諸国の利害が絡んだ大規模な戦争。","note":"ヨーロッパ秩序を大きく変え、主権国家体制へつながった。"},{"term":"ウェストファリア条約","reading":"うぇすとふぁりあじょうやく","meaning":"三十年戦争を終わらせ、各国の主権と領土を認め合った1648年の講和。","note":"近代的な国際秩序の出発点として扱われる。"}]},{"topic":"産業革命","cards":[{"term":"蒸気機関","reading":"じょうききかん","meaning":"蒸気の力で機械を動かす動力装置。ワットによる改良で広く使われるようになった。","note":"工場や交通機関を変え、産業革命の象徴となった技術。"},{"term":"工場制機械工業","reading":"こうじょうせいきかいこうぎょう","meaning":"工場に労働者を集め、機械で大量生産する仕組み。","note":"手工業や家内工業に代わる生産の中心になった。"},{"term":"綿工業","reading":"めんこうぎょう","meaning":"綿織物の生産から機械化が進んだ、産業革命の先頭を切った産業。","note":"紡績と織布の発明が連鎖し、他の産業へ広がった。"},{"term":"資本主義","reading":"しほんしゅぎ","meaning":"生産手段を持つ資本家が労働者を雇い、利潤を求めて生産する経済の仕組み。","note":"産業革命とともに確立し、社会問題も生んだ体制。"},{"term":"労働問題","reading":"ろうどうもんだい","meaning":"長時間労働や低賃金、児童労働など工場労働者の厳しい条件をめぐる問題。","note":"労働組合や社会主義思想が広がる背景になった。"},{"term":"都市化","reading":"としか","meaning":"産業の発展に伴い、人口が農村から都市へ集中する現象。","note":"スラムの形成や衛生問題など新しい社会課題を生んだ。"}]},{"topic":"フランス革命","cards":[{"term":"旧体制（アンシャン・レジーム）","reading":"きゅうたいせい（あんしゃん・れじーむ）","meaning":"革命前のフランスで、聖職者と貴族が特権を持った身分秩序。","note":"第三身分の不満が高まり、革命の標的となった体制。"},{"term":"三部会","reading":"さんぶかい","meaning":"聖職者・貴族・平民の三身分からなる議会。1789年に久しぶりに召集された。","note":"採決方法をめぐる対立が国民議会の結成につながった。"},{"term":"バスティーユ襲撃","reading":"ばすてぃーゆしゅうげき","meaning":"1789年7月14日、パリ民衆が王権の象徴とされた牢獄を襲った事件。","note":"フランス革命の始まりを象徴する出来事とされる。"},{"term":"人権宣言","reading":"じんけんせんげん","meaning":"自由・平等・国民主権などをうたった1789年の宣言。正式名は人間と市民の権利の宣言。","note":"近代民主主義の原則を示し、後の憲法に影響を与えた。"},{"term":"ロベスピエール","reading":"ろべすぴえーる","meaning":"革命政府を率い、恐怖政治を行ったジャコバン派の指導者。","note":"テルミドールの反動で失脚し、革命の急進期が終わった。"},{"term":"ナポレオン","reading":"なぽれおん","meaning":"革命の混乱を収めて権力を握り、皇帝となった軍人・政治家。","note":"ナポレオン法典を残し、ヨーロッパ各地へ革命の理念を広げた。"}]},{"topic":"世界市場の形成と植民地化","cards":[{"term":"産業資本主義","reading":"さんぎょうしほんしゅぎ","meaning":"工場生産を担う産業資本が中心となった19世紀の資本主義の段階。","note":"自由貿易を求める動きと結びつき、世界市場が広がった。"},{"term":"インド大反乱とイギリス領インド","reading":"いんどだいはんらんといぎりすりょういんど","meaning":"1857年の反乱を機に東インド会社が解散し、イギリスが直接支配した体制。","note":"ムガル帝国が正式に終わり、植民地支配が強まった。"},{"term":"アヘン戦争","reading":"あへんせんそう","meaning":"アヘン貿易をめぐりイギリスと清が戦った戦争。南京条約で香港などが割譲された。","note":"中国が欧米列強の圧力にさらされる転機になった。"},{"term":"オスマン帝国の改革","reading":"おすまんていこくの改革","meaning":"タンジマートなど、西欧を手本に軍制や法制度を改めようとした改革。","note":"帝国の衰退を食い止める試みだったが、列強の干渉も受けた。"},{"term":"アフリカ分割","reading":"あふりかぶんかつ","meaning":"19世紀末、ヨーロッパ列強がアフリカ大陸を植民地として分け合った動き。","note":"ベルリン会議を経て短期間に進み、現在の国境問題の背景にもなった。"},{"term":"民族運動の始まり","reading":"みんぞくうんどうのはじまり","meaning":"植民地支配に対して独立や権利を求める運動がアジア・アフリカで芽生えた動き。","note":"インド国民会議の結成などが初期の代表例。"}]},{"topic":"第一次世界大戦","cards":[{"term":"三国同盟と三国協商","reading":"さんごくどうめいとさんごくきょうしょう","meaning":"ドイツ中心の同盟と英仏露の協商が対立した、開戦前の国際関係の枠組み。","note":"列強の対立が大戦へ拡大する土台になった。"},{"term":"サラエボ事件","reading":"さらえぼじけん","meaning":"1914年、オーストリア皇位継承者が暗殺された事件。","note":"第一次世界大戦が始まる直接のきっかけになった。"},{"term":"総力戦","reading":"そうりょくせん","meaning":"国民や経済全体を戦争に動員し、戦線と銃後が一体となった戦争の形。","note":"第一次世界大戦で本格化し、被害の規模を大きくした。"},{"term":"ヴェルサイユ条約","reading":"ゔぇるさいゆじょうやく","meaning":"第一次世界大戦後に連合国とドイツの間で結ばれた講和条約。","note":"ドイツに重い賠償などを課し、後の不満の種にもなった。"},{"term":"国際連盟","reading":"こくさいれんめい","meaning":"第一次世界大戦後に作られた、平和維持を目指す初の国際機関。","note":"アメリカが不参加だったことなどが限界として指摘される。"},{"term":"ロシア革命","reading":"ろしあかくめい","meaning":"1917年に帝政が倒れ、ソヴィエト政権が生まれた革命。","note":"大戦中の社会不安を背景に起こり、世界に大きな影響を与えた。"}]},{"topic":"第二次世界大戦","cards":[{"term":"ファシズムの台頭","reading":"ふぁしずむのたいとう","meaning":"イタリアのムッソリーニらが率いた全体主義的な運動や体制の広がり。","note":"恐慌後の不安を背景にし、ドイツのナチズムとも並べられる。"},{"term":"第二次世界大戦の開始","reading":"だいにじせかいたいせんのかいし","meaning":"1939年、ドイツのポーランド侵攻をきっかけに始まった世界規模の戦争。","note":"イギリスとフランスの宣戦布告でヨーロッパ全体へ広がった。"},{"term":"日中戦争と太平洋戦争","reading":"にっちゅうせんそうとたいへいようせんそう","meaning":"1937年からの中国との戦争と、1941年からの対米英戦争を指す日本の戦争。","note":"アジア・太平洋地域に大きな被害をもたらした流れ。"},{"term":"ミッドウェー海戦とスターリングラード","reading":"みっどうぇーかいせんとすたーりんぐらーど","meaning":"太平洋と独ソ戦で連合国側が反攻へ転じるきっかけとなった二つの戦い。","note":"1942〜43年ごろの大戦の転換点として並べて扱われる。"},{"term":"連合国の戦後構想","reading":"れんごうこくのせんごこうそう","meaning":"大西洋憲章やヤルタ会談などで話し合われた、戦後の国際秩序の設計。","note":"国際連合の設立や冷戦の始まりにもつながった構想。"},{"term":"戦争の終結","reading":"せんそうのしゅうけつ","meaning":"1945年にドイツと日本が降伏し、第二次世界大戦が終わったこと。","note":"その後の占領や国際秩序の再編が始まる区切りになった。"}]},{"topic":"冷戦とその終結","cards":[{"term":"冷戦","reading":"れいせん","meaning":"アメリカとソ連が直接戦わずに対立し続けた第二次世界大戦後の状態。","note":"核兵器の存在が、正面衝突を避けさせる背景になった。"},{"term":"NATOとワルシャワ条約機構","reading":"なとーとわるしゃわじょうやくきこう","meaning":"西側と東側がそれぞれ作った軍事同盟の組織。","note":"冷戦下のヨーロッパを二分する対立の枠組みとなった。"},{"term":"朝鮮戦争","reading":"ちょうせんせんそう","meaning":"1950〜53年、南北に分かれた朝鮮半島で起きた戦争。米ソ中などが関与した。","note":"冷戦がアジアで熱い戦争になった代表例で、休戦のまま続く。"},{"term":"キューバ危機","reading":"きゅーばきき","meaning":"1962年、キューバへのソ連の核ミサイル配備をめぐり米ソが緊迫した事件。","note":"核戦争寸前とされ、その後の緊張緩和のきっかけにもなった。"},{"term":"ベトナム戦争","reading":"べとなむせんそう","meaning":"南北ベトナムの対立にアメリカが深く介入した戦争。1975年に北側が勝利した。","note":"アメリカ社会に大きな傷を残し、冷戦の限界も示した。"},{"term":"冷戦の終結","reading":"れいせんのしゅうけつ","meaning":"1989年のマルタ会談などで米ソ対立の終わりが確認され、ソ連も解体した流れ。","note":"東西対立の時代が終わり、国際秩序が組み替わった転換点。"}]},{"topic":"グローバル化と現代の課題","cards":[{"term":"グローバル化","reading":"ぐろーばるか","meaning":"人・物・お金・情報が国境を越えて結びつきを強める現代の動き。","note":"経済の効率を高める一方、格差や文化の摩擦も生んでいる。"},{"term":"WTOと自由貿易","reading":"だぶりゅーてぃーおーとじゆうぼうえき","meaning":"世界貿易機関を中心に、関税などを下げて貿易を広げようとする仕組み。","note":"GATTの後継として1995年に発足した体制。"},{"term":"南北問題と格差","reading":"なんぼくもんだいとかくさ","meaning":"豊かな先進国と発展途上国の間の経済格差をめぐる問題。","note":"資源価格や貿易条件などが背景となり、現代も続く課題。"},{"term":"地球環境問題","reading":"ちきゅうかんきょうもんだい","meaning":"地球温暖化や生物多様性の減少など、国境を越えて取り組むべき環境の課題。","note":"国際会議や条約による協力が必要とされる分野。"},{"term":"地域紛争と難民","reading":"ちいきふんそうとなんみん","meaning":"民族や宗教、領土などをめぐる紛争と、それにより住まいを追われる人々の問題。","note":"冷戦後も各地で続き、人道支援の課題となっている。"},{"term":"SDGs","reading":"えすでぃーじーず","meaning":"2030年までに達成を目指す持続可能な開発目標。17の目標からなる。","note":"貧困や環境など世界の課題をまとめた国連の枠組み。"}]}]},{"subject":"倫理","topics":[{"topic":"人間の心のあり方","cards":[{"term":"ホモ・サピエンス","reading":"ほも・さぴえんす","meaning":"ラテン語で「知恵のある人」を意味し、言葉や思考によって世界を理解しようとする人間の側面を表す呼び名。","note":"人間を考える出発点として、道具を作る存在という見方と並べて押さえる。"},{"term":"ホモ・ファーベル","reading":"ほも・ふぁーべる","meaning":"「作る人」という意味で、道具を作り使い、環境を作り変えながら生きてきた人間の姿を表す。","note":"知るだけでなく作ることで生きるという、人間のもう一つの特徴を示す。"},{"term":"青年期","reading":"せいねんき","meaning":"子どもから大人へ移る時期で、身体の変化とともに自分や将来について深く考えるようになる段階。","note":"このテーマでは、悩みながら自分らしさを探す時期として扱われる。"},{"term":"アイデンティティ","reading":"あいでんてぃてぃ","meaning":"「自分は自分である」という感覚や、自分らしさについてのまとまった意識のこと。","note":"青年期の中心的な課題であり、進路や価値観を考える土台になる。"},{"term":"認知","reading":"にんち","meaning":"外の出来事を受け取り、理解し、判断する心のはたらきのこと。","note":"感情と並ぶ心の働きとして、物事の捉え方が行動に影響する点が重要。"},{"term":"感情","reading":"かんじょう","meaning":"喜びや不安など、出来事に対して心が動く状態のこと。","note":"理性だけで割り切れない人間の心を理解する手がかりになる。"}]},{"topic":"ギリシャの哲学者たち","cards":[{"term":"ソクラテス","reading":"そくらてす","meaning":"古代ギリシャの哲学者で、問答を重ねて相手に自らの無知に気づかせ、よく生きることを探った。","note":"対話を通じて真理を探る姿勢が、後の西洋哲学の出発点となった。"},{"term":"無知の知","reading":"むちのち","meaning":"自分が本当は知らないことを自覚している状態のこと。ソクラテスが大切にした態度。","note":"知ったつもりにならず学び続ける姿勢として、このテーマの核になる。"},{"term":"プラトン","reading":"ぷらとん","meaning":"ソクラテスの弟子で、目に見える世界の奥にある永遠の真実を考えた哲学者。","note":"イデア論を唱え、理想の国家のあり方も論じた。"},{"term":"イデア","reading":"いであ","meaning":"個々の物事の原型となる、永遠で完全な本質のこと。プラトンの中心概念。","note":"目に見える物は不完全でも、その元となる姿があるという考え方を示す。"},{"term":"アリストテレス","reading":"ありすとてれす","meaning":"プラトンの弟子で、現実の物事を観察し分類しながら、その目的や原因を考えた哲学者。","note":"イデアを現実から離さず、身近な世界の中で本質を探った点が対照的。"},{"term":"ソフィスト","reading":"そふぃすと","meaning":"古代ギリシャで弁論や政治の技術を教えた人々の総称。","note":"相対的なものの見方を広めた一方、ソクラテスやプラトンから批判も受けた。"}]},{"topic":"仏教の思想","cards":[{"term":"ゴータマ","reading":"ごーたま","meaning":"仏教を開いた人物の名で、釈迦とも呼ばれる。苦しみの原因を見つめ、悟りへの道を示した。","note":"仏教思想の中心人物として、生涯と教えの出発点を押さえる。"},{"term":"四苦八苦","reading":"しくはっく","meaning":"生まれること、老いること、病むこと、死ぬことなど、人生に避けがたい苦しみがあるという見方。","note":"仏教がなぜ苦しみからの解放を目指すのかを理解する入口になる。"},{"term":"煩悩","reading":"ぼんのう","meaning":"欲や怒り、迷いなど、心を乱して苦しみを生む働きのこと。","note":"苦しみの原因とされ、これを滅することが修行の目標とされた。"},{"term":"解脱","reading":"げだつ","meaning":"煩悩による苦しみの束縛から解き放たれ、悟りの境地に達すること。","note":"ゴータマが目指し、仏教の実践の到達点とされる状態。"},{"term":"大乗仏教","reading":"だいじょうぶっきょう","meaning":"自分だけでなく、すべての人々の救いを目指す仏教の流れ。","note":"日本に伝わった仏教の多くがこの流れに属し、菩薩の考え方が特徴。"},{"term":"縁起","reading":"えんぎ","meaning":"すべての物事は単独で存在せず、互いに関わり合いながら成り立っているという考え方。","note":"固定的な実体を否定する、仏教らしい世界観の土台になる。"}]},{"topic":"キリスト教とイスラム教","cards":[{"term":"イエス","reading":"いえす","meaning":"キリスト教の中心人物で、神の愛と隣人への愛を説いたとされる。","note":"その生涯と教えが、キリスト教の信仰の核になっている。"},{"term":"隣人愛","reading":"りんじんあい","meaning":"身近な人々だけでなく、困っている人や敵をも含めて大切にする愛の考え方。","note":"キリスト教倫理を代表する実践として、このテーマで中心的に扱われる。"},{"term":"聖書","reading":"せいしょ","meaning":"キリスト教の聖典で、旧約と新約から成り、神と人間の関わりやイエスの教えが記される。","note":"信仰と生活の基準となる書物として位置づけられる。"},{"term":"ムハンマド","reading":"むはんまど","meaning":"イスラム教の預言者で、神の啓示を受けたとされ、その言葉が後にまとめられた。","note":"イスラム教の成立を理解するうえで欠かせない人物。"},{"term":"コーラン","reading":"こーらん","meaning":"イスラム教の聖典で、ムハンマドが受けたとされる神の啓示を集めたもの。","note":"信仰だけでなく生活の指針としても読まれる点が特徴。"},{"term":"五行","reading":"ごぎょう","meaning":"イスラム教徒が日常で実践すべき信仰告白や礼拝、喜捨などの行いの柱のこと。","note":"信じるだけでなく、日々の実践を重んじるイスラム教の姿を示す。"}]},{"topic":"中国の思想","cards":[{"term":"孔子","reading":"こうし","meaning":"儒教の祖とされる思想家で、人としての道徳や社会の秩序のあり方を説いた。","note":"仁と礼を中心とする教えが、中国思想の大きな土台となった。"},{"term":"仁","reading":"じん","meaning":"人を思いやり、大切にする心のこと。儒教で最も重んじられた徳。","note":"家族への愛情を出発点に、社会全体へ広げていくことが求められた。"},{"term":"礼","reading":"れい","meaning":"人間関係や社会の秩序を保つための、具体的な振る舞いや決まりのこと。","note":"仁という内面の心を、実際の行動として表すものとされた。"},{"term":"孟子の性善説","reading":"もうしのせいぜんせつ","meaning":"人間には生まれつき善に向かう芽生えがあり、育てることで善くなれるという孟子の考え。","note":"四端の心を伸ばすことが、王道政治の基礎になるとされた。"},{"term":"荀子の性悪説","reading":"じゅんしのせいあくせつ","meaning":"人間の欲望を放置すると争いが生じるため、礼による教育や訓練が必要だとする荀子の考え。","note":"性善説と対比され、後天的な努力を重視する点が特徴。"},{"term":"老子の無為自然","reading":"ろうしのむいしぜん","meaning":"人為的な作為を控え、自然の流れに任せて生きることをよしとする老子の考え。","note":"儒教の礼による秩序とは異なる、道家の生き方を示す。"},{"term":"荘子の万物斉同","reading":"そうしのばんぶつせいどう","meaning":"物事の価値や区別は相対的で、万物は本来等しく一つながりだとする荘子の見方。","note":"小さな価値判断にとらわれない、自由な精神を説く考え方。"}]},{"topic":"近代の哲学者","cards":[{"term":"デカルト","reading":"でかると","meaning":"「我思う、ゆえに我あり」で知られ、疑いを徹底して確実な知識の基礎を探った哲学者。","note":"近代哲学の出発点とされ、合理論の代表とされる。"},{"term":"合理論","reading":"ごうりろん","meaning":"知識の確かさは感覚よりも理性による思考に由来すると考える立場。","note":"デカルトら大陸の哲学者に代表され、経験論と対比される。"},{"term":"経験論","reading":"けいけんろん","meaning":"知識は経験や感覚を通じて得られると考える立場。","note":"ロックやヒュームらが代表し、合理論との対比で理解する。"},{"term":"カント","reading":"かんと","meaning":"合理論と経験論を統合しようとし、人間が認識できる範囲と道徳の基礎を問い直した哲学者。","note":"義務に基づく道徳や、認識の仕組みの考察で知られる。"},{"term":"ベンサム","reading":"べんさむ","meaning":"幸福を量として考え、社会全体の幸福を最大にすることを道徳の基準とした思想家。","note":"功利主義の創始者として、次の社会思想への橋渡しになる。"},{"term":"ニーチェ","reading":"にーちぇ","meaning":"既存の道徳や価値観を批判し、自ら価値を創造して生きることを説いた哲学者。","note":"「神は死んだ」という言葉で、近代の価値転換を象徴する存在。"}]},{"topic":"社会変革の思想と現代思想","cards":[{"term":"功利主義","reading":"こうりしゅぎ","meaning":"行為の正しさを、その結果として生じる幸福の大きさによって判断する考え方。","note":"ベンサムとミルが代表で、社会制度を評価する基準にもなった。"},{"term":"ミルの功利主義","reading":"みるのこうりしゅぎ","meaning":"幸福の量だけでなく質も重視し、自由の大切さを守ろうとしたミルの功利主義。","note":"ベンサムの考えを発展させ、個人の自由との両立を図った点が特徴。"},{"term":"社会主義思想","reading":"しゃかいしゅぎしそう","meaning":"生産手段を社会全体で所有・管理し、貧富の差をなくそうとする考え方の総称。","note":"資本主義が生んだ格差や労働問題への批判から広がった。"},{"term":"実証主義","reading":"じっしょうしゅぎ","meaning":"確かめられる事実や科学的な方法に基づく知識だけを信頼しようとする立場。","note":"コントが代表し、近代の科学重視の流れを表す思想。"},{"term":"実存主義","reading":"じつぞんしゅぎ","meaning":"人間はあらかじめ決まった本質を持たず、自らの選択によって自分を作っていくとする考え方。","note":"サルトルらが代表し、自由と責任を重く見る点が特徴。"},{"term":"構造主義","reading":"こうぞうしゅぎ","meaning":"個人の意識よりも、その背後にある社会や文化の仕組みに注目して人間を理解しようとする考え方。","note":"レヴィ＝ストロースらが代表し、現代思想に大きな影響を与えた。"}]},{"topic":"日本の思想","cards":[{"term":"神道","reading":"しんとう","meaning":"自然や祖先などに宿る神を敬い、祭りを通じて共同体と結びついてきた日本固有の信仰。","note":"日本の思想の土台の一つとして、外来思想との関わりの中で捉える。"},{"term":"浄土信仰","reading":"じょうどしんこう","meaning":"阿弥陀仏の救いを信じ、極楽浄土への往生を願う信仰のこと。","note":"平安末期の不安な社会の中で広がり、鎌倉仏教へつながった。"},{"term":"法然","reading":"ほうねん","meaning":"念仏を唱えることで誰もが救われると説き、浄土宗を開いた僧。","note":"専修念仏を唱え、身分によらない救いの道を示した。"},{"term":"親鸞","reading":"しんらん","meaning":"法然の弟子で、阿弥陀仏の力にすべてを委ねる救いを説き、浄土真宗を開いた僧。","note":"悪人正機説で知られ、自分の力に頼らない信仰を深めた。"},{"term":"朱子学","reading":"しゅしがく","meaning":"宇宙や社会の秩序を理によって説明し、身分秩序や道徳の根拠とした儒学の一派。","note":"江戸幕府に採用され、武士の学問や教育の中心となった。"},{"term":"本居宣長","reading":"もとおりのりなが","meaning":"『古事記』などの研究を通じて日本固有の精神を探り、国学を大成した学者。","note":"外来思想の影響を離れて古典を読み直そうとした点が特徴。"},{"term":"福沢諭吉","reading":"ふくざわゆきち","meaning":"学問の大切さと人の独立を説き、近代的な教育や社会のあり方を示した思想家。","note":"『学問のすゝめ』で知られ、明治の啓蒙思想を代表する。"}]},{"topic":"現代の諸課題と倫理","cards":[{"term":"生命倫理","reading":"せいめいりんり","meaning":"医療や科学技術の進歩に伴い、生命の始まりや終わり、人間の尊厳をどう扱うか考える分野。","note":"臓器移植や生殖医療など、答えが一つでない問題を扱う。"},{"term":"環境倫理","reading":"かんきょうりんり","meaning":"自然や将来世代に対して人間がどのような責任を持つかを考える分野。","note":"人間中心の見方を見直し、持続可能な社会を目指す土台になる。"},{"term":"科学技術と倫理","reading":"かがくぎじゅつとりんり","meaning":"便利さを生む技術の利用に伴う危険や責任を、倫理の面から考える視点のこと。","note":"AIや遺伝子技術など、新しい技術ほど問われやすいテーマ。"},{"term":"正義","reading":"せいぎ","meaning":"人々の権利や利益、負担を公平に配分するための基準や考え方のこと。","note":"福祉や格差の問題を考えるときの中心概念になる。"},{"term":"多文化共生","reading":"たぶんかきょうせい","meaning":"文化や価値観の異なる人々が、違いを認め合いながら共に暮らすこと。","note":"グローバル化が進む社会で、互いの尊厳を守る姿勢が求められる。"},{"term":"平和の実現","reading":"へいわのじつげん","meaning":"戦争や暴力をなくすだけでなく、貧困や差別などの構造的な問題も解くことを含む目標。","note":"国際協力や人権尊重と結びつけて考えられる現代的課題。"}]}]},{"subject":"政治・経済","topics":[{"topic":"民主政治の基本原理","cards":[{"term":"国民主権","reading":"こくみんしゅけん","meaning":"国の政治の最終的な決定権は国民全体にあるという原理。","note":"民主政治の根幹であり、日本国憲法の基本原則の一つでもある。"},{"term":"社会契約説","reading":"しゃかいけいやくせつ","meaning":"国家は人々が互いに約束を結んで作ったものだと説明する考え方。","note":"ホッブズ、ロック、ルソーがそれぞれ異なる形で論じ、国民主権の土台となった。"},{"term":"権力分立","reading":"けんりょくぶんりつ","meaning":"国家の権力を複数の機関に分け、互いに抑制させることで権力の集中を防ぐ仕組み。","note":"モンテスキューが説いた三権分立が代表例として扱われる。"},{"term":"法の支配","reading":"ほうのしはい","meaning":"権力者も法に従わなければならず、人の恣意的な支配を認めないという考え方。","note":"立憲主義と結びつき、人権保障の基礎になる原理。"},{"term":"基本的人権","reading":"きほんてきじんけん","meaning":"人間が生まれながらに持つとされる、侵すことのできない基本的な権利の総称。","note":"自由権や平等権、社会権などが含まれ、民主政治の目的とされる。"},{"term":"立憲主義","reading":"りっけんしゅぎ","meaning":"憲法によって国家権力を制限し、国民の権利を守ろうとする考え方。","note":"法の支配と並んで、近代民主政治の前提となる原理。"}]},{"topic":"日本国憲法の基本原則","cards":[{"term":"国民主権","reading":"こくみんしゅけん","meaning":"国の政治のあり方を最終的に決める力は国民にあるという原則。","note":"日本国憲法の三つの基本原則の一つとして、前文と第1条に示される。"},{"term":"平和主義","reading":"へいわしゅぎ","meaning":"戦争や武力による争いを否定し、平和を守ろうとする原則。","note":"憲法第9条の戦争放棄と結びつき、日本国憲法を特徴づける原則。"},{"term":"基本的人権の尊重","reading":"きほんてきじんけんのそんちょう","meaning":"すべての人の基本的人権を、侵すことのできない永久の権利として大切にする原則。","note":"三つの基本原則の一つで、憲法の多くの条文に具体化されている。"},{"term":"象徴天皇制","reading":"しょうちょうてんのうせい","meaning":"天皇が日本国と国民統合の象徴とされ、国政に関する権能を持たない制度。","note":"国民主権と両立する形で憲法第1条に定められた仕組み。"},{"term":"立憲主義","reading":"りっけんしゅぎ","meaning":"憲法を最高の基準として権力を縛り、国民の権利を保障しようとする考え方。","note":"日本国憲法の基本原則を支える考えとして、法の支配と合わせて理解する。"},{"term":"最高法規","reading":"さいこうほうき","meaning":"憲法が国の法秩序の中で最も強い効力を持ち、他の法令は憲法に反してはならないこと。","note":"憲法第98条に定められ、違憲審査制の根拠にもなる。"}]},{"topic":"国会・内閣・裁判所","cards":[{"term":"三権分立","reading":"さんけんぶんりつ","meaning":"立法・行政・司法の三つの権力を別々の機関に担わせ、互いにチェックさせる仕組み。","note":"国会・内閣・裁判所の関係を理解する全体の枠組みになる。"},{"term":"国会","reading":"こっかい","meaning":"国民の代表である議員から成り、法律を作る国の唯一の立法機関。","note":"衆議院と参議院の二院制をとり、国権の最高機関とされる。"},{"term":"衆議院の優越","reading":"しゅうぎいんのゆうえつ","meaning":"衆参両院の意見が異なる場合に、一定の条件で衆議院の議決を優先する仕組み。","note":"任期が短く解散もある衆議院が、民意をより反映すると考えられるため認められる。"},{"term":"内閣","reading":"ないかく","meaning":"行政権を担う機関で、内閣総理大臣と国務大臣から構成される。","note":"国会に対して連帯して責任を負う、議院内閣制の中心機関。"},{"term":"裁判所","reading":"さいばんしょ","meaning":"司法権を担い、法に基づいて紛争を解決し、法令の合憲性を審査する機関。","note":"最高裁判所と下級裁判所があり、司法権の独立が保障される。"},{"term":"議院内閣制","reading":"ぎいんないかくせい","meaning":"内閣が議会の信任に基づいて成立し、議会に責任を負う政治制度。","note":"日本やイギリスで採用され、大統領制と対比される。"}]},{"topic":"選挙と政党","cards":[{"term":"選挙の四原則","reading":"せんきょのよんげんそく","meaning":"普通・平等・直接・秘密の四つから成る、民主的な選挙の基本原則。","note":"誰が、どのように投票するかを定める土台として押さえる。"},{"term":"小選挙区制","reading":"しょうせんきょくせい","meaning":"一つの選挙区から一人の当選者を出す選挙制度。","note":"大きな政党に有利で政権交代が起こりやすい一方、死票が多くなりやすい。"},{"term":"比例代表制","reading":"ひれいだいひょうせい","meaning":"政党の得票率に応じて議席を配分する選挙制度。","note":"少数意見が反映されやすい反面、小党が乱立しやすい面がある。"},{"term":"小選挙区比例代表並立制","reading":"しょうせんきょくひれいだいひょうへいりつせい","meaning":"小選挙区制と比例代表制を組み合わせ、別々に投票して議席を決める日本の衆議院の制度。","note":"二つの制度の長所を取り入れようとする仕組みとして理解する。"},{"term":"一票の格差","reading":"いっぴょうのかくさ","meaning":"選挙区によって一票の価値に差が生じる問題のこと。","note":"議員定数の配分が見直されないと広がり、法の下の平等との関係で問題になる。"},{"term":"与党と野党","reading":"よとうとやとう","meaning":"政権を担う政党を与党、政権の外から政府を監視・批判する政党を野党という。","note":"政党政治の中で、政権担当とチェック機能という役割の違いを示す。"}]},{"topic":"需要と供給","cards":[{"term":"需要","reading":"じゅよう","meaning":"ある価格のもとで、消費者が買おうとする財やサービスの量のこと。","note":"価格が下がると増える傾向があり、需要曲線で表される。"},{"term":"供給","reading":"きょうきゅう","meaning":"ある価格のもとで、生産者が売ろうとする財やサービスの量のこと。","note":"価格が上がると増える傾向があり、供給曲線で表される。"},{"term":"均衡価格","reading":"きんこうかかく","meaning":"需要量と供給量がちょうど一致する価格のこと。","note":"市場で価格が落ち着く目安となり、需要・供給曲線の交点で決まる。"},{"term":"需要曲線","reading":"じゅようきょくせん","meaning":"価格と需要量の関係を表した曲線で、通常は右下がりになる。","note":"価格以外の条件が変わると曲線そのものが左右に移動する。"},{"term":"供給曲線","reading":"きょうきゅうきょくせん","meaning":"価格と供給量の関係を表した曲線で、通常は右上がりになる。","note":"生産費用などの条件が変わると曲線そのものが移動する。"},{"term":"価格の自動調節機能","reading":"かかくのじどうちょうせつきのう","meaning":"余りや不足が生じたときに価格が変動し、需要と供給を一致へ導く市場の働き。","note":"市場機構の基本として、均衡価格が決まる仕組みと結びつく。"}]},{"topic":"金融のしくみ","cards":[{"term":"直接金融","reading":"ちょくせつきんゆう","meaning":"資金を必要とする者が、株式や債券を発行して投資家から直接資金を集める方法。","note":"証券市場を通じる方法で、間接金融と対比される。"},{"term":"間接金融","reading":"かんせつきんゆう","meaning":"銀行などの金融機関が預金を集め、それを企業などへ貸し出す形の資金の流れ。","note":"日本で中心的な役割を果たしてきた金融の仕組み。"},{"term":"日本銀行","reading":"にっぽんぎんこう","meaning":"日本の中央銀行で、紙幣の発行や物価の安定、金融システムの安定を担う機関。","note":"金融政策の実施主体として、このテーマの中心に置かれる。"},{"term":"金融政策","reading":"きんゆうせいさく","meaning":"中央銀行が金利や資金量を調整して、景気や物価を安定させようとする政策。","note":"政策金利の操作が代表的な手段となる。"},{"term":"政策金利","reading":"せいさくきんり","meaning":"中央銀行が金融政策の目安として誘導する短期金利のこと。","note":"市中の金利全体に影響し、景気を冷やす・温める調整に使われる。"},{"term":"株式","reading":"かぶしき","meaning":"株式会社が資金を集めるために発行する証券で、保有者は出資者として議決権などを持つ。","note":"直接金融の代表例であり、価格変動のリスクも伴う。"},{"term":"預金保険制度","reading":"よきんほけんせいど","meaning":"金融機関が破綻したときに、一定額までの預金を保護する仕組み。","note":"預金者の不安を抑え、金融システムの安定を守る役割を持つ。"}]},{"topic":"財政のしくみ","cards":[{"term":"財政","reading":"ざいせい","meaning":"政府が税金などで収入を得て、公共サービスなどに支出する活動のこと。","note":"資源配分や所得再分配、景気安定という三つの役割が知られる。"},{"term":"直接税","reading":"ちょくせつぜい","meaning":"税を負担する人と納める人が同じ税で、所得税や法人税が代表例。","note":"所得に応じて負担を調整しやすく、累進課税と結びつきやすい。"},{"term":"間接税","reading":"かんせつぜい","meaning":"税を負担する人と納める人が異なる税で、消費税が代表例。","note":"広く集めやすい一方、所得の低い人ほど負担感が重くなる面がある。"},{"term":"累進課税","reading":"るいしんかぜい","meaning":"所得が高くなるほど高い税率が適用される課税の仕方。","note":"所得の再分配を進める仕組みとして、所得税に採用されている。"},{"term":"予算","reading":"よさん","meaning":"政府の一年間の収入と支出の計画で、国会の議決を経て成立するもの。","note":"財政を民主的にコントロールするための重要な手続き。"},{"term":"公債","reading":"こうさい","meaning":"政府が資金不足を補うために発行する借金の証書で、国が発行するものは国債と呼ばれる。","note":"将来世代への負担の問題と合わせて、財政健全化の文脈で扱われる。"}]},{"topic":"日本経済の発展と課題","cards":[{"term":"高度経済成長","reading":"こうどけいざいせいちょう","meaning":"1950年代半ばから1970年代初めにかけて、日本経済が急速に拡大した時期のこと。","note":"所得の増加と生活の変化をもたらした、日本経済の転機として扱われる。"},{"term":"バブル経済","reading":"ばぶるけいざい","meaning":"地価や株価が実体以上に膨らみ、その後急激に崩れた1980年代末前後の経済状況。","note":"その崩壊後の長期停滞が、その後の日本経済の課題につながった。"},{"term":"中小企業","reading":"ちゅうしょうきぎょう","meaning":"規模の小さい企業の総称で、日本の企業数の大半を占める。","note":"大企業との格差や人手不足などが課題として取り上げられる。"},{"term":"雇用と労働問題","reading":"こようとろうどうもんだい","meaning":"非正規雇用の増加や長時間労働、賃金の伸び悩みなど、働く人をめぐる課題の総称。","note":"少子高齢化や働き方改革の議論と結びつけて理解する。"},{"term":"社会保障制度","reading":"しゃかいほしょうせいど","meaning":"病気や老齢、失業などのリスクに備え、国が生活を支える仕組みの総称。","note":"年金・医療・介護・生活保護などが柱となり、財政との関係も重要。"},{"term":"少子高齢化","reading":"しょうしこうれいか","meaning":"出生数が減り、高齢者の割合が高まる人口構造の変化のこと。","note":"社会保障の担い手不足という課題を通じて、日本経済全体に影響する。"}]},{"topic":"国際政治と国際連合","cards":[{"term":"国際法","reading":"こくさいほう","meaning":"国家間の関係を規律する法で、条約や国際慣習法などから成る。","note":"国内法と違い強制力に限界がある点が、国際政治の特質と関わる。"},{"term":"国際連合","reading":"こくさいれんごう","meaning":"第二次世界大戦後に設立された、世界の平和と安全、国際協力を目的とする国際機関。","note":"総会や安全保障理事会などの機関から成り、国際政治の中心舞台となる。"},{"term":"安全保障理事会","reading":"あんぜんほしょうりじかい","meaning":"国際の平和と安全の維持に主要な責任を持つ、国連の機関の一つ。","note":"常任理事国に拒否権があることが、大きな特徴であり課題でもある。"},{"term":"常任理事国","reading":"じょうにんりじこく","meaning":"安全保障理事会に常時加わる五つの国で、決議への拒否権を持つ。","note":"国連が大国の協力なしには機能しにくい仕組みを示す存在。"},{"term":"PKO","reading":"ぴーけーおー","meaning":"停戦の監視や治安維持などを担う国連平和維持活動の略称。","note":"紛争地域で中立的に活動する仕組みとして、国連の役割を具体化する。"},{"term":"拒否権","reading":"きょひけん","meaning":"安全保障理事会の常任理事国が、決議案に反対して成立を止められる権利。","note":"大国同士の対立があると国連が動けなくなる原因として議論される。"}]},{"topic":"国際経済とグローバル化","cards":[{"term":"比較優位","reading":"ひかくゆうい","meaning":"各国が相対的に得意な財の生産に特化し貿易することで、全体の利益が増えるという考え方。","note":"貿易がなぜ利益を生むのかを説明する、国際経済の基本理論。"},{"term":"国際収支","reading":"こくさいしゅうし","meaning":"一定期間に一国と外国との間で行われた経済取引をまとめた記録のこと。","note":"経常収支や資本収支などから、国の対外的な経済関係が分かる。"},{"term":"為替相場","reading":"かわせそうば","meaning":"異なる通貨を交換するときの比率のこと。","note":"円高・円安の変動を通じて、輸出入や物価に影響を与える。"},{"term":"IMF","reading":"あいえむえふ","meaning":"国際通貨基金の略称で、為替の安定や国際収支に困る国への融資を行う国際機関。","note":"世界銀行とともに、戦後の国際経済体制を支える機関の一つ。"},{"term":"世界銀行","reading":"せかいぎんこう","meaning":"発展途上国への長期の融資や技術支援を行い、開発を助ける国際機関。","note":"貧困削減を目的とし、IMFとは役割の重点が異なる。"},{"term":"WTO","reading":"だぶりゅーてぃーおー","meaning":"世界貿易機関の略称で、自由貿易のルール作りと貿易紛争の解決を担う機関。","note":"GATTを引き継いで設立され、グローバル化のルール面を支える。"},{"term":"GATT","reading":"がっと","meaning":"関税と貿易に関する一般協定の略称で、関税引き下げなどを進めた戦後の貿易の枠組み。","note":"後にWTOへ発展した経緯を押さえることで、自由貿易の流れが分かる。"}]}]},{"subject":"情報","topics":[{"topic":"情報社会と法律","cards":[{"term":"個人情報","reading":"こじんじょうほう","meaning":"氏名や住所、生年月日など、特定の個人を識別できる情報のこと。生きている個人に関する情報が対象になる。","note":"このテーマでは、本人の同意なく集めたり他人に渡したりしないことが大切な情報として扱う。"},{"term":"著作権","reading":"ちょさくけん","meaning":"小説や音楽、写真、プログラムなどの創作物を創った人に認められる権利。許可なくコピーや公開をされないよう守る仕組みである。","note":"知的財産権の一つで、ネット上の文章や画像を使うときのルールの中心になる。"},{"term":"知的財産権","reading":"ちてきざいさんけん","meaning":"人の創作や発明など、形のない知的成果を財産として守る権利の総称。著作権のほか特許権や商標権などが含まれる。","note":"情報社会で創作活動を支える大きな枠組みとして、著作権の上位の考え方に位置づく。"},{"term":"情報モラル","reading":"じょうほうもらる","meaning":"情報社会で安全に、相手を傷つけずに行動するために必要な判断力や心構えのこと。法律以前のマナーや配慮も含む。","note":"SNSの投稿や転送の場面で、法律とあわせて行動を考える基準になる。"},{"term":"フェイクニュース","reading":"ふぇいくにゅーす","meaning":"事実でないのに本当の報道のように見せかけた、うその情報のこと。注目を集めたり人をだましたりする目的で広まることがある。","note":"出典や他の報道と比べるなど、情報の確かさを確かめる姿勢が求められる例である。"},{"term":"デジタルデバイド","reading":"でじたるでばいど","meaning":"パソコンやインターネットを使える人と使えない人の間に生じる、情報や機会の格差のこと。","note":"情報社会の便利さが一部の人に偏らないようにするための課題として取り上げる。"}]},{"topic":"2進数と情報量","cards":[{"term":"2進数","reading":"にしんすう","meaning":"0と1の2種類の数字だけを使って数を表す方法。コンピュータ内部の計算や記録はこの表し方を基本にしている。","note":"ふだん使う10進数と変換し合うことが、このテーマの計算の中心になる。"},{"term":"ビット","reading":"びっと","meaning":"情報量の最小の単位。0か1かのどちらか一方を表すことができ、データの大きさを数える土台になる。","note":"バイトを構成する小さな単位で、2進数の1桁と対応している。"},{"term":"バイト","reading":"ばいと","meaning":"8ビットをひとまとめにした情報量の単位。英数字1文字分程度のデータを表す目安として使われる。","note":"ファイルの大きさはキロバイトやメガバイトなど、バイトを基準に表すことが多い。"},{"term":"16進数","reading":"じゅうろくしんすう","meaning":"0から9とAからFまでの16種類の記号で数を表す方法。長い2進数を短く分かりやすく書き換えるために使う。","note":"2進数の4桁が16進数の1桁に対応するため、色の指定やアドレス表示でよく見かける。"},{"term":"文字コード","reading":"もじこーど","meaning":"文字と数値の対応を決めた取り決めのこと。コンピュータは決められた数値に置き換えて文字を処理している。","note":"同じ数値でも規格が違うと別の文字になるため、文字化けの原因を考える手がかりになる。"},{"term":"デジタル化","reading":"でじたるか","meaning":"音や画像、文字などの情報を数値に変換してコンピュータで扱える形にすること。","note":"情報を正確に複製したり加工したりしやすくなる、この単元全体の出発点になる考え方である。"}]},{"topic":"情報デザインとメディア","cards":[{"term":"情報デザイン","reading":"じょうほうでざいん","meaning":"伝えたい内容を受け手に分かりやすく届くよう、情報の内容や見せ方、流れを工夫して設計すること。","note":"見た目の飾りだけでなく、何をどの順で伝えるかまで含めた全体の設計を指す。"},{"term":"ユニバーサルデザイン","reading":"ゆにばーさるでざいん","meaning":"年齢や障がいの有無などにかかわらず、できるだけ多くの人が使いやすいように製品や情報を設計する考え方。","note":"情報デザインでは、誰もが内容を受け取れるようにする視点として位置づく。"},{"term":"配色","reading":"はいしょく","meaning":"使う色の組み合わせや使い方のこと。色の対比や明るさの差によって、読みやすさや印象が大きく変わる。","note":"背景と文字の色の組み合わせは、可読性を左右する具体的な工夫の一つである。"},{"term":"可読性","reading":"かどくせい","meaning":"文字や文章がどれだけ読みやすいかを表す性質。文字の大きさや行間、色の対比などが影響する。","note":"受け手が無理なく内容を読み取れるかどうかを判断する物差しになる。"},{"term":"メディアの特性","reading":"めでぃあのとくせい","meaning":"新聞、テレビ、ウェブなど、情報を伝える手段ごとに異なる届き方や得意・不得意のこと。","note":"伝えたい内容に合った手段を選ぶために、比較して考える対象になる。"},{"term":"情報の流れの設計","reading":"じょうほうのながれのせっけい","meaning":"受け手がどの順番で情報に触れ、どう理解していくかを考えて、画面や資料の構成を組み立てること。","note":"見出しやボタンの配置など、迷わず目的にたどり着くための工夫に結びつく。"}]},{"topic":"アルゴリズムとプログラミング","cards":[{"term":"アルゴリズム","reading":"あるごりずむ","meaning":"問題を解くための手順を、順序立てて明確に表したもの。同じ手順をたどれば誰でも同じ結果にたどり着く。","note":"プログラムを作る前に考える、処理の設計図にあたる中心的な考え方である。"},{"term":"順次・分岐・反復","reading":"じゅんじ・ぶんき・はんぷく","meaning":"処理を上から順に行う順次、条件で進み方を変える分岐、同じ処理を繰り返す反復のこと。この3つで基本的な処理を組み立てられる。","note":"フローチャートの記号と対応し、アルゴリズムを表す基本の3構造として学ぶ。"},{"term":"フローチャート","reading":"ふろーちゃーと","meaning":"処理の流れを、決められた形の記号と矢印で図に表したもの。分岐や繰り返しも視覚的に追える。","note":"アルゴリズムを他の人に伝えたり、間違いを見つけたりするときに使う表現方法である。"},{"term":"変数","reading":"へんすう","meaning":"プログラムの中で数値や文字などのデータを一時的に入れておく、名前の付いた箱のようなもの。","note":"計算の途中結果を保持し、繰り返しや分岐の処理で使い回す役割を持つ。"},{"term":"探索","reading":"たんさく","meaning":"たくさんのデータの中から、目的のデータを見つけ出す処理のこと。端から順に調べる方法や、半分ずつ絞る方法がある。","note":"整列と並んで、データ処理の代表的なアルゴリズムとして効率の違いを比べる。"},{"term":"整列（ソート）","reading":"せいれつ（そーと）","meaning":"データを小さい順や大きい順など、決めた順番に並べ替える処理のこと。ソートとも呼ばれる。","note":"並べ替え方によって処理の速さが変わるため、アルゴリズムの効率を考える題材になる。"}]},{"topic":"モデル化とシミュレーション","cards":[{"term":"モデル化","reading":"もでるか","meaning":"現実の物事から必要な要素だけを取り出し、単純化して表すこと。複雑な現象を扱いやすくするための工夫である。","note":"シミュレーションを行う前提として、最初に行う作業に位置づく。"},{"term":"シミュレーション","reading":"しみゅれーしょん","meaning":"モデルを使って、現実の現象をコンピュータ上などで再現し、試しに動かしてみること。模擬実験ともいえる。","note":"実際には試しにくい条件を変えて結果を比べられる点が、このテーマの強みである。"},{"term":"乱数","reading":"らんすう","meaning":"規則性なく現れる数の列のこと。くじ引きや確率的な現象をモデルで再現するときに使う。","note":"確率的なモデルで、偶然に左右される現象を扱うための道具になる。"},{"term":"モデルの仮定","reading":"もでるのかてい","meaning":"モデルを作るときに置く前提や割り切りのこと。何を省略し、何を単純化したかを示すものである。","note":"結果が現実とずれる理由を考えるとき、まず見直すべき点として扱う。"},{"term":"結果の検証","reading":"けっかのけんしょう","meaning":"シミュレーションで得られた結果が、現実のデータや予想と合っているかを確かめること。","note":"モデルや仮定を見直すきっかけになり、シミュレーションの最後の大事な手順である。"},{"term":"確率的なモデル","reading":"かくりつてきなもでる","meaning":"偶然の要素を取り入れて、結果が確率で変わる現象を表したモデルのこと。行列の待ち時間などの再現に使われる。","note":"乱数を使って何度も試し、傾向をつかむ使い方と結びついて学ぶ。"}]},{"topic":"ネットワークとセキュリティ","cards":[{"term":"プロトコル","reading":"ぷろとこる","meaning":"コンピュータ同士が通信するときの手順や約束事のこと。互いに同じ決まりに従うことでデータをやり取りできる。","note":"ネットワークの土台となる決まりで、IPやウェブ閲覧の決まりもこの一種である。"},{"term":"IPアドレス","reading":"あいぴーあどれす","meaning":"ネットワークにつながる機器を識別するために割り当てられる番号。通信の宛先や送り元を示す住所のような役割を持つ。","note":"パケットを届ける場面で、宛先を指定するために使われる情報である。"},{"term":"パケット","reading":"ぱけっと","meaning":"ネットワークで送るデータを小さく分割した単位のこと。宛先などの情報を付けて送られ、受け手側で元に戻される。","note":"大きなデータでも回線を効率よく使って送れるようにする仕組みの中心である。"},{"term":"暗号化","reading":"あんごうか","meaning":"データを決まった方法で読みにくい形に変換し、鍵を持つ人だけが元に戻せるようにすること。","note":"通信を途中で見られても内容が分からないようにする、セキュリティの基本技術である。"},{"term":"認証","reading":"にんしょう","meaning":"利用者や機器が本当に本人・本物であるかを確かめる仕組み。パスワードや指紋などを使って行う。","note":"なりすましを防ぐ役割があり、暗号化と並ぶセキュリティの柱の一つである。"},{"term":"コンピュータウイルス","reading":"こんぴゅーたういるす","meaning":"コンピュータに侵入してデータを壊したり情報を盗んだりする、不正なプログラムの総称。","note":"感染を防ぐ対策や、怪しいファイルを開かない注意と結びつけて学ぶ対象である。"}]},{"topic":"データの活用","cards":[{"term":"代表値","reading":"だいひょうち","meaning":"データ全体の傾向を一つの数で表した値。平均値や中央値、最頻値などが代表例である。","note":"散らばったデータを要約して比べるための、最初の整理の道具になる。"},{"term":"散布図","reading":"さんぷず","meaning":"二つの数量の関係を点の集まりで表したグラフ。各データの二つの値を縦軸と横軸に置いて打つ。","note":"相関があるかどうかを目で確かめるために使うグラフである。"},{"term":"相関関係","reading":"そうかんかんけい","meaning":"一方の値が変わると、もう一方の値も一定の傾向で変わるような、二つの事柄の結びつきのこと。","note":"原因と結果の関係とは別物であり、混同しないことがこのテーマの注意点になる。"},{"term":"ビッグデータ","reading":"びっぐでーた","meaning":"従来の方法では扱いきれないほど大量で多様なデータの集まり。集めて分析することで新たな傾向が見えることがある。","note":"データ活用の広がりを示す例で、収集と分析の両面から考える対象である。"},{"term":"データベース","reading":"でーたべーす","meaning":"データを決まった形式で整理して蓄え、必要なときに検索や取り出しができるようにした仕組み。","note":"大量のデータを効率よく活用するための土台として位置づく。"},{"term":"オープンデータ","reading":"おーぷんでーた","meaning":"国や自治体などが公開し、誰でも自由に利用や再配布ができるようにしたデータのこと。","note":"社会でデータを役立てる取り組みの例として、出典を示して使う点も含めて学ぶ。"}]}]},{"subject":"体育","topics":[{"topic":"安全の確保","cards":[{"term":"危険の予測と回避","reading":"きけんのよそくと かいひ","meaning":"運動やスポーツの場面で起こりうる事故やけがをあらかじめ考え、危ない状況を避ける行動を取ること。","note":"安全の確保の出発点であり、用具や天候、体調の確認と結びつく考え方である。"},{"term":"熱中症","reading":"ねっちゅうしょう","meaning":"暑さで体の水分や塩分のバランスが崩れ、体温調節がうまくいかなくなった状態。重くなると命に関わる。","note":"水分補給や休憩、気温への注意など、予防の具体策とセットで学ぶ。"},{"term":"RICE処置","reading":"らいすしょち","meaning":"打撲や捻挫などの急性のけがへの応急処置で、安静・冷却・圧迫・挙上の頭文字を取ったもの。","note":"けがをした直後の対応として、安全の確保の実践的な内容に位置づく。"},{"term":"ウォーミングアップ","reading":"うぉーみんぐあっぷ","meaning":"運動の前に体を徐々に動かして体温や心拍を上げ、筋肉や関節を運動に備えさせる準備運動。","note":"けがの予防と運動の効果を高める両面から、運動前の基本として扱う。"},{"term":"落雷への対応","reading":"らくらいへのたいおう","meaning":"雷が近づいたときに屋外の活動を中断し、安全な建物などに避難するなどの行動のこと。","note":"天候の急変に備える危険回避の具体例として取り上げる。"},{"term":"AED","reading":"えーいーでぃー","meaning":"心臓が正常に動かなくなった人に電気ショックを与え、正常な動きに戻すことを助ける医療機器。自動体外式除細動器の略。","note":"緊急時の救命処置の流れの中で、心肺蘇生とあわせて場所や使い方を知っておく機器である。"}]},{"topic":"スポーツ外傷・障害","cards":[{"term":"スポーツ外傷","reading":"すぽーつがいしょう","meaning":"一度の大きな力で急に起こるけがのこと。転倒や衝突による骨折、捻挫、打撲などが当てはまる。","note":"スポーツ障害と区別する基本用語で、発生のしかたが急である点が特徴である。"},{"term":"スポーツ障害","reading":"すぽーつしょうがい","meaning":"同じ動作の繰り返しなどで小さな負担が積み重なり、徐々に生じる痛みや故障のこと。","note":"スポーツ外傷と対になる用語で、使いすぎが主な原因として位置づく。"},{"term":"オーバーユース","reading":"おーばーゆーす","meaning":"筋肉や関節などを休ませずに使いすぎること。スポーツ障害の代表的な原因とされる。","note":"練習量の調整や休息の大切さを考える手がかりになる言葉である。"},{"term":"疲労骨折","reading":"ひろうこっせつ","meaning":"同じ部位に小さな力が繰り返し加わり、骨にひびが入るように折れる状態。スポーツ障害の一つである。","note":"一度の衝撃で折れる通常の骨折と違い、負担の積み重ねで起こる例として学ぶ。"},{"term":"シンスプリント","reading":"しんすぷりんと","meaning":"走る動作の繰り返しなどで、すねの内側に痛みが出るスポーツ障害。初心者や練習量が急に増えた人に起こりやすい。","note":"オーバーユースによる障害の具体例として取り上げる。"},{"term":"障害の予防","reading":"しょうがいのよぼう","meaning":"練習量の調整や正しいフォーム、筋力づくり、休息などで、スポーツ障害を未然に防ぐ取り組み。","note":"外傷・障害の知識を自分の運動生活に生かす、まとめの視点になる。"}]},{"topic":"健康づくりのための運動","cards":[{"term":"有酸素運動","reading":"ゆうさんそうんどう","meaning":"酸素を取り込みながら長時間続けられる、比較的軽めの運動。ウォーキングやジョギングなどが当てはまる。","note":"健康づくりの中心的な運動として、強さや時間の目安とあわせて学ぶ。"},{"term":"身体活動基準","reading":"しんたいかつどうきじゅん","meaning":"健康を保つために望ましい運動や生活活動の量を示した、国の目安のこと。年齢層ごとに示される。","note":"自分に必要な運動量を考えるときの物差しとして位置づく。"},{"term":"メッツ","reading":"めっつ","meaning":"運動の強さを表す単位。安静にしているときを1として、その何倍のエネルギーを消費するかで示す。","note":"種類の違う運動の強さを同じ物差しで比べるために使う。"},{"term":"ロコモティブシンドローム","reading":"ろこもてぃぶしんどろーむ","meaning":"骨や関節、筋肉などの運動器の衰えにより、立つ・歩くといった移動機能が低下した状態。略してロコモともいう。","note":"将来の要介護を防ぐために、若いうちからの運動習慣と結びつけて学ぶ。"},{"term":"サルコペニア","reading":"さるこぺにあ","meaning":"加齢などによって筋肉の量が減り、筋力や身体機能が低下した状態のこと。","note":"ロコモの要因の一つでもあり、筋肉を保つ運動の大切さを示す言葉である。"},{"term":"メタボリックシンドローム","reading":"めたぼりっくしんどろーむ","meaning":"内臓脂肪がたまった状態に加え、高血圧や高血糖などが重なり、生活習慣病の危険が高まった状態。","note":"有酸素運動や生活習慣の見直しで改善を目指す対象として取り上げる。"}]},{"topic":"生涯スポーツ","cards":[{"term":"生涯スポーツ","reading":"しょうがいすぽーつ","meaning":"年齢や体力に応じて、生涯を通じて楽しみながら続けるスポーツのあり方や、その活動自体のこと。","note":"このテーマ全体の中心概念で、競技としてだけでなく楽しむ視点が大切にされる。"},{"term":"する・みる・ささえる","reading":"する・みる・ささえる","meaning":"スポーツへの関わり方を表す三つの言葉。自ら行う、観戦する、運営や指導などで支える関わり方を指す。","note":"生涯スポーツでは、競技者以外にも多様な関わり方が認められることを示す。"},{"term":"総合型地域スポーツクラブ","reading":"そうごうがたちいきすぽーつくらぶ","meaning":"地域の人々が主体となり、複数の種目を、子どもから高齢者までがそれぞれのレベルで楽しめる地域のスポーツクラブ。","note":"身近な地域で生涯スポーツを支える仕組みの代表例として位置づく。"},{"term":"ライフステージ","reading":"らいふすてーじ","meaning":"子どもの頃、青年期、壮年期、高齢期など、人生の段階のこと。各段階で体力や生活が異なる。","note":"各段階に合ったスポーツの選び方を考えるための枠組みになる。"},{"term":"スポーツ基本法","reading":"すぽーつきほんほう","meaning":"スポーツに関する基本的な理念や、国や自治体の役割などを定めた法律。2011年に制定された。","note":"生涯スポーツを社会として推進する法的な土台として扱う。"},{"term":"スポーツ庁","reading":"すぽーつちょう","meaning":"スポーツの振興に関する国の政策を担う行政機関。文部科学省の外局として設置されている。","note":"国の立場からスポーツ推進を進める中心機関として位置づく。"}]},{"topic":"ライフスタイルに応じたスポーツ","cards":[{"term":"ライフスタイル","reading":"らいふすたいる","meaning":"仕事や学校、家庭などを含む、その人の生活の送り方や習慣全体のこと。","note":"スポーツを生活に取り入れるとき、前提として見つめる自分の生活そのものを指す。"},{"term":"スポーツライフの設計","reading":"すぽーつらいふのせっけい","meaning":"自分の生活や体力、目的に合わせて、いつ・何を・どのくらい行うかという運動の計画を立てること。","note":"このテーマの中心的な活動で、現状の把握と目標設定を経て行う。"},{"term":"現状の把握","reading":"げんじょうのはあく","meaning":"今の体力や運動習慣、生活時間などを確かめ、自分の現在の状態を知ること。","note":"設計の最初の手順であり、無理のない目標を立てる土台になる。"},{"term":"目標設定","reading":"もくひょうせってい","meaning":"運動で何を目指すかを具体的で達成可能な形で決めること。期間や数値を入れると進み具合が分かりやすい。","note":"現状の把握の次に行う手順で、続ける意欲を保つ役割も持つ。"},{"term":"すきま時間の活用","reading":"すきまじかんのかつよう","meaning":"通学や休憩などの短い空き時間を使って、軽い運動やストレッチを取り入れる工夫のこと。","note":"忙しい生活でも運動を続けるための、具体的な工夫の一つである。"},{"term":"PDCAサイクル","reading":"ぴーでぃーしーえーさいくる","meaning":"計画、実行、評価、改善の四つを繰り返して物事をよくしていく進め方のこと。","note":"立てたスポーツライフの計画を見直し、続けやすく改善していく方法として使う。"}]},{"topic":"スポーツ推進の取り組み","cards":[{"term":"スポーツ庁","reading":"すぽーつちょう","meaning":"国のスポーツ政策を担当する行政機関で、競技力の向上から地域のスポーツ振興まで幅広く担う。","note":"推進の取り組みでは、国レベルの施策の中心として位置づく。"},{"term":"総合型地域スポーツクラブ","reading":"そうごうがたちいきすぽーつくらぶ","meaning":"地域住民が運営の中心となり、多種目・多世代・多志向を特徴とする地域のスポーツクラブ。","note":"地域レベルで推進を支える具体的な仕組みとして取り上げる。"},{"term":"スポーツボランティア","reading":"すぽーつぼらんてぃあ","meaning":"大会の運営補助や地域の活動支援など、報酬を目的とせずスポーツを支える活動や、その参加者のこと。","note":"ささえる関わり方の代表例で、大会や地域行事を成り立たせる存在である。"},{"term":"障がい者スポーツ","reading":"しょうがいしゃすぽーつ","meaning":"障がいのある人が参加するスポーツや、障がいに合わせて用具やルールを工夫したスポーツのこと。","note":"誰もがスポーツに関われる社会を目指す推進の柱の一つとして扱う。"},{"term":"スポーツツーリズム","reading":"すぽーつつーりずむ","meaning":"スポーツの観戦や参加を目的とした旅行や、それによる地域への人の流れのこと。","note":"スポーツが地域の活性化につながる側面を示す取り組みである。"},{"term":"レガシー","reading":"れがしー","meaning":"大きな大会などの開催をきっかけに、施設や文化、人材などの良い影響が開催後に社会に残るもののこと。遺産とも訳される。","note":"大会を一過性で終わらせず、推進の成果として残す視点を表す言葉である。"}]},{"topic":"豊かなスポーツライフの創造","cards":[{"term":"スポーツの多様な価値","reading":"すぽーつのたようなかち","meaning":"健康や体力だけでなく、楽しさや交流、感動、地域のつながりなど、スポーツが持つさまざまな良さのこと。","note":"このテーマ全体を貫く考え方で、勝敗以外の価値に目を向ける出発点になる。"},{"term":"フェアプレイ","reading":"ふぇあぷれい","meaning":"ルールを守り、相手や審判を尊重して正々堂々と競う姿勢のこと。","note":"スポーツの価値を守る基本的な心構えとして、ドーピングの対極にも置かれる。"},{"term":"ドーピング","reading":"どーぴんぐ","meaning":"競技で不正に力を高めるために、禁止された薬物や方法を使うこと。健康を害し、公平さも損なう。","note":"フェアプレイに反する行為として、なぜ許されないかを考える対象になる。"},{"term":"スポーツと交流","reading":"すぽーつとこうりゅう","meaning":"スポーツを通して世代や地域、国境を越えて人々が出会い、理解し合うつながりのこと。","note":"多様な価値の一つであり、豊かなスポーツライフを広げる側面として扱う。"},{"term":"スポーツと環境","reading":"すぽーつとかんきょう","meaning":"自然の中で行うスポーツや大会運営が環境に与える影響と、環境を守りながら楽しむ工夫のこと。","note":"スポーツを持続可能な形で続けるための視点として位置づく。"},{"term":"関わり方の変化","reading":"かかわりかたのへんか","meaning":"年齢や生活の変化に合わせて、する側からみる側、ささえる側へとスポーツとの関わり方が変わっていくこと。","note":"生涯にわたってスポーツと付き合う姿として、このテーマのまとめにあたる考え方である。"}]}]}];
